(function(A){Object.assign(A.D,{"G4790":{"l":"συνκοινωνέω","o":3,"ar":"<f>* <o>συν-κοινωνέω</o>، <g>-ῶ</g>، </f> <s><b>يشترك مع، أو يشارك في</b>: مع القابل للشيء، <r v=\"Eph.5.11\"></r>، <r v=\"Rev.18.4\"></r>؛ نفسه مع المضاف إليه للشخص، <r v=\"Phil.4.14\"></r>.†</s>","en":"<f>* <o>συν-κοινωνέω</o> (Rec. <g>συγκ-</g>), <g>-ῶ</g>, </f> <s><b>to have fellowship with or in</b> (in cl., c. gen. rei, dat. pers.): c. dat. rei, <r v=\"Eph.5.11\"></r>, <r v=\"Rev.18.4\"></r>; id. c. gen. pers., <r v=\"Phil.4.14\"></r>.†</s>"},"G4776":{"l":"περικαθίζω","o":2,"ar":"<f><o>περι-καθ-ίζω</o>،</f> <s n=\"1.\"><b>يطوِّق</b>، <b>يحاصر</b> (<r v=\"2Kgs.6.24\"></r>، <r v=\"1Macc.11.61\"></r>، وفي مواضع أخرى).</s> <s n=\"2.\"><b>يجلس حول</b>: <r v=\"Luke.22.55\"></r>.†</s>","en":"<f><o>περι-καθ-ίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2583\">חנה</h>, <h n=\"H3898\">לחם</h> ni., etc.;]</e> </et> <s n=\"1.\"><b>to invest</b>, <b>besiege</b> (Diod., <r v=\"2Kgs.6.24\"></r>, <r v=\"1Macc.11.61\"></r>, al.).</s> <s n=\"2.\"><b>to sit around</b>: <r v=\"Luke.22.55\"></r>, L, txt.†</s>"},"G4771":{"l":"σύ","o":2907,"ar":"<f><o>σύ</o>، </f> ضمير المخاطَب، <s><b>أنتَ، أنتم</b>، المضاف إليه <g>σοῦ</g>، القابل <g>σοί</g>، المنصوب <g>σέ</g>، الجمع <g>ὑμεῖς, -ῶν, -ῖν, -ᾶς</g> (ملحق (enclitic) في حالات المفرد غير المرفوعة، إلا بعد حرف الجر، مع أن <g>πρὸς σέ</g> ترد في <r v=\"Matt.25.39\"></r>). وحالة الرفع للتوكيد أو المقابلة: <r v=\"John.1.30\"></r>، <r v=\"John.1.42\"></r> <r v=\"John.4.10\"></r> <r v=\"John.5.33\"></r>، <r v=\"John.5.39\"></r>، <r v=\"John.5.44\"></r>، <r v=\"Acts.4.7\"></r>، <r v=\"Eph.5.32\"></r>؛ وكذلك ربما <g>σὺ εἶπας</g>، <r v=\"Matt.26.64\"></r>، وفي مواضع أخرى؛ قبل النداء، <r v=\"Matt.2.6\"></r>، <r v=\"Luke.1.76\"></r>، <r v=\"John.17.5\"></r>، وفي مواضع أخرى؛ وأحيانًا بلا توكيد، خاصةً ترجمةً لعبارة عبرية، مثلاً <g>υἱός μου εἶ σύ</g> (<h n=\"H1121,H859\">בְּנִי־אַתָּה</h>، <r v=\"Ps.2.7\"></r>)، <r v=\"Acts.13.33\"></r>. ويوضع المضاف إليه (<g>σοῦ, ὑμῶν</g>) أحيانًا قبل الاسم: <r v=\"Luke.7.48\"></r>، <r v=\"Luke.12.30\"></r>، وفي مواضع أخرى؛ وكذلك الملحق <g>σοῦ</g>، <r v=\"Matt.9.6\"></r>؛ وعن <g>τί ἐμοὶ κ. σοί</g>، انظر تحت مدخل <g>ἐγώ</g>.</s>","en":"<f><o>σύ</o>, </f> pron. of 2nd pers., <s><b>thou, you</b>, gen., <g>σοῦ</g>, dat., <g>σοί</g>, acc., <g>σέ</g>, pl., <g>ὑμεῖς, -ῶν, -ῖν, -ᾶς</g> (enclitic in oblique cases sing., except after prep. (BL, §48, 3), though <g>πρὸς σέ</g> occurs in <r v=\"Matt.25.39\"></r>). Nom. for emphasis or contrast: <r v=\"John.1.30\"></r>, <r v=\"John.1.42\"></r> <r v=\"John.4.10\"></r> <r v=\"John.5.33\"></r>, <r v=\"John.5.39\"></r>, <r v=\"John.5.44\"></r>, <r v=\"Acts.4.7\"></r>, <r v=\"Eph.5.32\"></r>; so also perhaps <g>σὺ εἶπας</g>, <r v=\"Matt.26.64\"></r>, al. (M, <i>Pr.</i>, 86); before voc., <r v=\"Matt.2.6\"></r>, <r v=\"Luke.1.76\"></r>, <r v=\"John.17.5\"></r>, al.; sometimes without emphasis (M, <i>Pr.</i>, 85f.), as also in cl., but esp. as rendering of Heb. phrase, e.g. <g>υἱός μου εἶ σύ</g> (<h n=\"H1121,H859\">בְּנִי־אַתָּה</h>, <r v=\"Ps.2.7\"></r>), <r v=\"Acts.13.33\"></r>. The gen. (<g>σοῦ, ὑμῶν</g>) is sometimes placed bef. the noun: <r v=\"Luke.7.48\"></r>, <r v=\"Luke.12.30\"></r>, al.; so also the enclitic <g>σοῦ</g>, <r v=\"Matt.9.6\"></r>; on <g>τί ἐμοὶ κ. σοί</g>, v.s. <g>ἐγώ</g>.</s>"},"G4716":{"l":"σταυρός","o":27,"ar":"<f>* <o>σταυρός</o>، <g>-οῦ, ὁ </g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>وتد</b> قائم أو <b>خازوق</b> </s> <s n=\"2.\">عن أداة الصلب الرومانية، <b>الصليب</b>: عن الصليب الذي تألّم عليه المسيح، <r v=\"Matt.27.32\"></r>، <r v=\"Matt.27.40\"></r>، <r v=\"Matt.27.42\"></r>، <r v=\"Mark.15.21\"></r>، <r v=\"Mark.15.30\"></r>، <r v=\"Mark.15.32\"></r>، <r v=\"Luke.23.26\"></r>، <r v=\"John.19.17\"></r>، <r v=\"John.19.19\"></r>، <r v=\"John.19.25\"></r>، <r v=\"John.19.31\"></r>، <r v=\"Col.2.14\"></r>، <r v=\"Heb.12.2\"></r>؛ <g>θάνατος σταυροῦ</g>، <r v=\"Phil.2.8\"></r>؛ <g>τ. αἷμα τοῦ σ.</g>، <r v=\"Col.1.20\"></r>. مجازيًا، في الأقوال المأثورة: <g>αἴρειν</g> (<g>λαμβάνειν, βαστάζειν</g>) <g>τὸν σ.</g>، <r v=\"Matt.10.38\"></r> <r v=\"Matt.16.24\"></r>، <r v=\"Mark.8.34\"></r> <r v=\"Mark.10.21\"></r>، <r v=\"Mark.15.21\"></r>، <r v=\"Luke.9.23\"></r> <r v=\"Luke.14.27\"></r> وكنايةً عن موت المسيح على الصليب: <r v=\"1Cor.1.17\"></r>، <r v=\"Gal.5.11\"></r> <r v=\"Gal.6.12\"></r>، <r v=\"Gal.6.14\"></r>، <r v=\"Eph.2.16\"></r>، <r v=\"Phil.3.18\"></r>؛ <g>ὁ λόγος ὁ τοῦ σ.</g>، <r v=\"1Cor.1.18\"></r>.†</s>","en":"<f>* <o>σταυρός</o>, <g>-οῦ, ὁ </g></f> <s n=\"1.\">an upright <b>pale</b> or <b>stake</b> (Hom., Hdt., Thuc., al.) </s> <s n=\"2.\">In late writers (Diod., Plut., al.) of the Roman instrument of crucifixion, <b>the Cross</b>: of the Cross on which Christ suffered, <r v=\"Matt.27.32\"></r>, <r v=\"Matt.27.40\"></r>, <r v=\"Matt.27.42\"></r>, <r v=\"Mark.15.21\"></r>, <r v=\"Mark.15.30\"></r>, <r v=\"Mark.15.32\"></r>, <r v=\"Luke.23.26\"></r>, <r v=\"John.19.17\"></r>, <r v=\"John.19.19\"></r>, <r v=\"John.19.25\"></r>, <r v=\"John.19.31\"></r>, <r v=\"Col.2.14\"></r>, <r v=\"Heb.12.2\"></r>; <g>θάνατος σταυροῦ</g>, <r v=\"Phil.2.8\"></r>; <g>τ. αἷμα τοῦ σ.</g>, <r v=\"Col.1.20\"></r>. Metaph., in proverbial sayings: <g>αἴρειν</g> (<g>λαμβάνειν, βαστάζειν</g>) <g>τὸν σ.</g>, <r v=\"Matt.10.38\"></r> <r v=\"Matt.16.24\"></r>, <r v=\"Mark.8.34\"></r> <r v=\"Mark.10.21\"></r>, <r v=\"Mark.15.21\"></r>, <r v=\"Luke.9.23\"></r> <r v=\"Luke.14.27\"></r> (for an interesting ex. of metaph. use in <g>π.</g>, v. MM, xxiii) By meton., for Christ's death on the Cross: <r v=\"1Cor.1.17\"></r>, <r v=\"Gal.5.11\"></r> <r v=\"Gal.6.12\"></r>, <r v=\"Gal.6.14\"></r>, <r v=\"Eph.2.16\"></r>, <r v=\"Phil.3.18\"></r>; <g>ὁ λόγος ὁ τοῦ σ.</g>, <r v=\"1Cor.1.18\"></r>.†</s>"},"G4704":{"l":"σπουδάζω","o":11,"ar":"<f><o>σπουδάζω</o></f> <s><b>يُسرع</b>؛ ومن ثمَّ، <b>يغار (يتحمّس)</b> أو <b>يتلهّف، يجتهد</b>: مع المصدر، <r v=\"Gal.2.10\"></r>، <r v=\"Eph.4.3\"></r>، <r v=\"1Thess.2.17\"></r>، <r v=\"2Tim.2.15\"></r> <r v=\"2Tim.4.9\"></r>، <r v=\"2Tim.4.21\"></r>، <r v=\"Titus.3.12\"></r>، <r v=\"Heb.4.11\"></r>، <r v=\"2Pet.1.10\"></r> <r v=\"2Pet.3.14\"></r>؛ مع المنصوب والمصدر، <r v=\"2Pet.1.15\"></r>.†</s>","en":"<f><o>σπουδάζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>σπουδή</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H926\">בּהל</h>ni.;] </e> </et> <s><b>to make haste</b>; hence, <b>to be zealous</b> or <b>eager, to give diligence</b>: c. inf. (v. M, <i>Pr.</i>, 205 f.), <r v=\"Gal.2.10\"></r>, <r v=\"Eph.4.3\"></r>, <r v=\"1Thess.2.17\"></r>, <r v=\"2Tim.2.15\"></r> <r v=\"2Tim.4.9\"></r>, <r v=\"2Tim.4.21\"></r>, <r v=\"Titus.3.12\"></r>, <r v=\"Heb.4.11\"></r>, <r v=\"2Pet.1.10\"></r> <r v=\"2Pet.3.14\"></r>; c. acc. et inf. (on this construction v. Mayor in l.; MM, xxiii), <r v=\"2Pet.1.15\"></r> (for other constructions v. LS, s.v.).†</s>"},"G4750":{"l":"στόμα","o":78,"ar":"<f><o>στόμα</o>، <g>-τος, τό </g></f> <s><b>الفم</b>: فم الإنسان، <r v=\"Matt.15.11\"></r>، <r v=\"John.19.29\"></r>، <r v=\"Acts.11.8\"></r>، وفي مواضع أخرى؛ فم الحيوانات، <r v=\"Matt.17.27\"></r>، <r v=\"2Tim.4.17\"></r> (مجازيًا)، <r v=\"Heb.11.33\"></r>، <r v=\"Jas.3.3\"></r>، وفي مواضع أخرى؛ مجازيًا، عن الجمادات، <g>ἤνοιξεν ἡ γῆ τὸ σ.</g>، <r v=\"Rev.12.16\"></r>؛ <g>σ. μαχαίρας</g> (العبرية <h n=\"H6310\">פִּי</h>־<h n=\"H2719\">חֶרֶב</h>، <r v=\"Gen.34.26\"></r> وفي مواضع أخرى)، <b>حدّ</b> السيف (فم السيف)، <r v=\"Luke.21.24\"></r>، <r v=\"Heb.11.34\"></r>؛ خاصةً عن الفم بوصفه عضو الكلام: عكس <g>καρδία</g>، <r v=\"Matt.12.34\"></r>، <r v=\"Rom.10.8\"></r>، <r v=\"Rom.10.10\"></r>؛ في عبارات مختلفة : <g>ἀνοίγειν τ. σ.</g> (انظر تحت مدخل <g>ἀνοίγω</g>)؛ <g>σ. πρὸς σ.</g> (<h n=\"H6310\">פֶּה</h> <h n=\"H413\">אֵל</h>־<h n=\"H6310\">פֶּה</h>، <r v=\"Num.12.8\"></r>)، <b>فمًا لفم (وجهًا لوجه)</b>، <r v=\"2John.1.12\"></r>، <r v=\"3John.1.14\"></r>؛ <g>διὰ τοῦ σ.</g> (عن الروح القدس)، <r v=\"Luke.1.70\"></r>، <r v=\"Acts.1.16\"></r>، وفي مواضع أخرى؛ <g>ἀπὸ (ἐκ) τοῦ σ.</g>، عن الكلام شفاهًا، <r v=\"Luke.22.71\"></r>، <r v=\"Acts.22.14\"></r>؛ <g>δόλος (ψεῦδος) ἐν τ. σ.</g>، <r v=\"1Pet.2.22\"></r>، <r v=\"Rev.14.5\"></r> <i>(السبعينية)</i>؛ مجازيًا، <g>ἡ ῥομφαία τοῦ σ.</g>، <r v=\"Rev.2.16\"></r>. وكنايةً عن الكلام : <r v=\"Matt.18.16\"></r> <i>(السبعينية)</i>، <r v=\"Luke.19.22\"></r> <r v=\"Luke.21.15\"></r>، <r v=\"2Cor.13.1\"></r> </s>","en":"<f><o>στόμα</o>, <g>-τος, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6433\">פֶּה</h> ;] </e> </et> <s><b>the mouth</b>: of man, <r v=\"Matt.15.11\"></r>, <r v=\"John.19.29\"></r>, <r v=\"Acts.11.8\"></r>, al.; of animals, <r v=\"Matt.17.27\"></r>, <r v=\"2Tim.4.17\"></r> (fig.), <r v=\"Heb.11.33\"></r>, <r v=\"Jas.3.3\"></r>, al.; fig., of inanimate things (<g>ποταμοῦ</g>, Hom.), <g>ἤνοιξεν ἡ γῆ τὸ σ.</g>, <r v=\"Rev.12.16\"></r>; <g>σ. μαχαίρας</g> (Heb. <h n=\"H6310\">פִּי</h>־<h n=\"H2719\">חֶרֶב</h>, <r v=\"Gen.34.26\"></r> al.), the <b>edge</b> of the sword, <r v=\"Luke.21.24\"></r>, <r v=\"Heb.11.34\"></r>; esp. of the mouth as the organ of speech: opp. to <g>καρδία</g>, <r v=\"Matt.12.34\"></r>, <r v=\"Rom.10.8\"></r>, <r v=\"Rom.10.10\"></r>; in various phrases (some cl., some resembling Hebrew; cf. Bl., § 40, 9): <g>ἀνοίγειν τ. σ.</g> (v.s. <g>ἀνοίγω</g>); <g>σ. πρὸς σ.</g> (<h n=\"H6310\">פֶּה</h> <h n=\"H413\">אֵל</h>־<h n=\"H6310\">פֶּה</h>, <r v=\"Num.12.8\"></r>; = cl., <g>κατὰ σ.</g>, Hdt., al.), <b>face to face</b>, <r v=\"2John.1.12\"></r>, <r v=\"3John.1.14\"></r>; <g>διὰ τοῦ σ.</g> (of the Holy Spirit), <r v=\"Luke.1.70\"></r>, <r v=\"Acts.1.16\"></r>, al.; <g>ἀπὸ (ἐκ) τοῦ σ.</g> (cf. <g>ἀπὸ σ. εἰπεῖν</g>, Plat., al.), of speaking by word of mouth, <r v=\"Luke.22.71\"></r>, <r v=\"Acts.22.14\"></r>; <g>δόλος (ψεῦδος) ἐν τ. σ.</g>, <r v=\"1Pet.2.22\"></r>, <r v=\"Rev.14.5\"></r> <i>(LXX)</i>; metaph., <g>ἡ ῥομφαία τοῦ σ.</g>, <r v=\"Rev.2.16\"></r>. By meton., for speech (Soph.): <r v=\"Matt.18.16\"></r> <i>(LXX)</i>, <r v=\"Luke.19.22\"></r> <r v=\"Luke.21.15\"></r>, <r v=\"2Cor.13.1\"></r> </s>"},"G4789":{"l":"συνκληρονόμος","o":4,"ar":"<f>*† <o>συν-κληρο-νόμος</o>، <g>-ου, ὁ</g> </f> <s><b>شريك في الميراث، وارث معه</b>: <r v=\"Rom.8.17\"></r>، <r v=\"Eph.3.6\"></r>؛ مع المضاف إليه للشيء، <r v=\"Heb.11.9\"></r>، <r v=\"1Pet.3.7\"></r> .†</s>","en":"<f>*† <o>συν-κληρο-νόμος</o> (Rec. <g>συγκ-</g>), <g>-ου, ὁ</g> </f> <s><b>a co-inheritor, fellow-heir</b>: <r v=\"Rom.8.17\"></r>, <r v=\"Eph.3.6\"></r>; c. gen. rei, <r v=\"Heb.11.9\"></r>, <r v=\"1Pet.3.7\"></r> (for exx., v. Deiss., <i>LAE</i>, 88 f.).†</s>"},"G4769":{"l":"στύλος","o":4,"ar":"<f><o>στύλος (T</o>، <g>στῦλος</g>، كما في اليونانية الكلاسيكية)، <g>-ου, ὁ</g></f> <s><b>عمود</b>، يُنظر إليه خاصةً كدعامة: <g>σ. πυρός</g>، <r v=\"Rev.10.1\"></r>؛ <g>σ. ἐν τ. ναῷ</g>، مجازيًا، <r v=\"Rev.3.12\"></r>، وكذلك مجازيًا، <r v=\"Gal.2.9\"></r>؛ <g>τ. ἀληθείας</g>، <r v=\"1Tim.3.15\"></r>.†</s>","en":"<f><o>στύλος (T</o>, <g>στῦλος</g>, as in cl.), <g>-ου, ὁ</g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5982\">עַמּוּד</h>, also for <h n=\"H7175\">קֶרֶשׁ</h>, etc. ;]</e> </et> <s><b>a pillar</b>, regarded especially as a support: <g>σ. πυρός</g>, <r v=\"Rev.10.1\"></r>; <g>σ. ἐν τ. ναῷ</g>, fig., <r v=\"Rev.3.12\"></r>, Metaph., <r v=\"Gal.2.9\"></r>; <g>τ. ἀληθείας</g>, <r v=\"1Tim.3.15\"></r>.†</s>"},"G4742":{"l":"στίγμα","o":1,"ar":"<f><o>στίγμα</o>، <g> -τος, τό</g></f> <s><b>وَسْم موشوم</b> أو <b>سِمة</b>: <g>τὰ σ. τοῦ Ἰησοῦ</g>، <r v=\"Gal.6.17\"></r>.†</s>","en":"<f><o>στίγμα</o>, <g> -τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>στίζω</g>, <b>to prick</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Song.1.11\"></r> (<h n=\"H5351\">נְקֻדָּה</h>) * ;]</e> </et> <s><b>a tattoed mark</b> or <b>brand</b>: <g>τὰ σ. τοῦ Ἰησοῦ</g>, <r v=\"Gal.6.17\"></r> (v. Lft., in l.; Deiss., <i>BS</i>, 349; <i>LAE</i>, 303; MM, xxiii).†</s>"},"G4754":{"l":"στρατεύω","o":7,"ar":"<f><o>στρατεύω </o> وبالصيغة الوسطى (deponent) <g>-ομαι</g>، وهكذا دائمًا في العهد الجديد </f> <s>يُقال عن القائد: <b>يشنّ حربًا، يحارب</b>، و(في الغالب) عن الجنود الذين يخدمون تحت قيادته: <b>يتجنّد، يخدم جنديًّا</b>: <r v=\"Luke.3.14\"></r>، <r v=\"1Cor.9.7\"></r>، <r v=\"2Tim.2.4\"></r>. مجازيًا، عن الصراع الروحي: <b>يحارب، يشنّ حربًا</b>: <r v=\"2Cor.10.3\"></r>، <r v=\"1Tim.1.18\"></r>، <r v=\"Jas.4.1\"></r>، <r v=\"1Pet.2.11\"></r>.†</s>","en":"<f><o>στρατεύω </o> and depon., <g>-ομαι</g>, so always in NT </f> <et> <e t=\"derivation\">(&lt; <g>στρατός</g>, <b>an encamped army</b>), </e> <e t=\"septuagint\">[in LXX for מההּ hith., <h n=\"H3318\">יצא</h>, <h n=\"H6635\">צבא</h>; metaph., <r v=\"4Macc.9.23\"></r> ;] </e> </et> <s>used of the general, <b>to make war, do battle</b>, and (chiefly) of the soldiers serving under him, <b>to serve as a soldier</b>: <r v=\"Luke.3.14\"></r>, <r v=\"1Cor.9.7\"></r>, <r v=\"2Tim.2.4\"></r>. Metaph. (cf. MM, ii, xxiii), of spiritual conflict, <b>to war, make war</b>: <r v=\"2Cor.10.3\"></r>, <r v=\"1Tim.1.18\"></r>, <r v=\"Jas.4.1\"></r>, <r v=\"1Pet.2.11\"></r>.†</s>"},"G4757":{"l":"στρατιώτης","o":26,"ar":"<f><o>στρατιώτης</o>، <g>-ου, ὁ </g></f> <s><b>جندي، عسكري</b>: <r v=\"Matt.8.9\"></r>، <r v=\"Mark.15.16\"></r>، <r v=\"John.19.2\"></r>، <r v=\"Acts.10.7\"></r>، وفي مواضع أخرى؛ مجازيًا، <g>σ. Χριστοῦ Ἰησ.</g>، <r v=\"2Tim.2.3\"></r>.†</s>","en":"<f><o>στρατιώτης</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX; <r v=\"2Sam.23.8\"></r> B<i>1</i>, <r v=\"2Macc.5.12\"></r> <r v=\"2Macc.14.39\"></r>, <r v=\"3Macc.3.12\"></r> ; IV Mac<i>3</i> * ;] </e> </et> <s><b>a soldier</b>: <r v=\"Matt.8.9\"></r>, <r v=\"Mark.15.16\"></r>, <r v=\"John.19.2\"></r>, <r v=\"Acts.10.7\"></r>, al.; metaph., <g>σ. Χριστοῦ Ἰησ.</g>, <r v=\"2Tim.2.3\"></r>.†</s>"},"G4783":{"l":"συνκατάθεσις","o":1,"ar":"<f>*† <o>συν-κατά-θεσις</o>، <g>-εως, ἡ</g></f> <s><b>وفاق، موافقة</b>: <r v=\"2Cor.6.16\"></r>.†</s>","en":"<f>*† <o>συν-κατά-θεσις</o> (Rec <g>συγκ-</g>), <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συνκατατίθημι</g></x>) </e> </et> <s><b>concord, agreement</b>: <r v=\"2Cor.6.16\"></r> (Polyb., Plut., al.).†</s>"},"G4726":{"l":"στεναγμός","o":2,"ar":"<f><o>στεναγμός</o>، <g>-οῦ, ὁ</g></f> <s><b>أنين</b>: <r v=\"Acts.7.34\"></r> (في السبعينية <g>κραυγή</g>)، <r v=\"Rom.8.26\"></r>.†</s>","en":"<f><o>στεναγμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>στενάζω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H585\">אֲנָחָה</h>, <h n=\"H603\">אֲנָקָה</h>, <h n=\"H5009\">נְאָקָה</h>, etc. ;] </e> </et> <s><b>a groaning</b>: <r v=\"Acts.7.34\"></r> (LXX <g>κραυγή</g>), <r v=\"Rom.8.26\"></r>.†</s>"},"G4741":{"l":"στηρίζω","o":13,"ar":"<f><o>στηρίζω </o></f> <s><b>ثبّت، أرسى، أوطد</b>: <r v=\"Luke.16.26\"></r>؛ <g>τ. πρόσωτον</g> (أي ثبّت وجهه، عزم بإصرار) (<r v=\"Ezek.6.2\"></r>، <r v=\"Ezek.13.17\"></r>، وفي مواضع أخرى): <r v=\"Luke.9.51\"></r>. مجازيًا: <b>ثبّت، شدّد، وطّد</b>: مع المنصوب: <r v=\"Luke.22.32\"></r>، <r v=\"Acts.18.23\"></r>، <r v=\"Rom.1.11\"></r>، <r v=\"Rom.16.25\"></r>، <r v=\"1Thess.3.2\"></r>، <r v=\"1Thess.3.13\"></r>، <r v=\"2Thess.3.3\"></r>، <r v=\"Jas.5.8\"></r>، <r v=\"1Pet.5.10\"></r>، <r v=\"Rev.3.2\"></r>؛ وكذلك يليه <g>ἐν</g>: <r v=\"2Thess.2.17\"></r>، <r v=\"2Pet.1.12\"></r>.†</s>","en":"<f><o>στηρίζω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5564\">סמך</h>, <h n=\"H7760\">שׂוּם</h> (<h n=\"H7760\">שׂים</h>), etc. ;]</e> </et> <s><b>to fix, set fast, make fast</b>: <r v=\"Luke.16.26\"></r>; <g>τ. πρόσωτον</g> (<r v=\"Ezek.6.2\"></r> <r v=\"Ezek.13.17\"></r>, al.; v. Dalman, <i>Words</i>, 30 f.), <r v=\"Luke.9.51\"></r>. Metaph., <b>to confirm, establish</b>: c., acc., <r v=\"Luke.22.32\"></r>, <r v=\"Acts.18.23\"></r>, <r v=\"Rom.1.11\"></r> <r v=\"Rom.16.25\"></r>, <r v=\"1Thess.3.2\"></r>, <r v=\"1Thess.3.13\"></r>, <r v=\"2Thess.3.3\"></r>, <r v=\"Jas.5.8\"></r>, <r v=\"1Pet.5.10\"></r>, <r v=\"Rev.3.2\"></r>; id. seq. <g>ἐν</g>, <r v=\"2Thess.2.17\"></r>, <r v=\"2Pet.1.12\"></r>.†</s>"},"G4733":{"l":"στερέωμα","o":1,"ar":"<f><o>στερέωμα</o>، <g>-τος, τό</g></f> <s><b>جسم صلب</b>؛ </s> <s n=\"(a)\"><b>سند، أساس</b> (في اليونانية الكلاسيكية)؛ مجازيًا: <b>قوة</b> (<r v=\"Ps.17.1-Ps.17.15\"></r>، <r v=\"Ps.70.1-Ps.70.5\"></r>، <r v=\"1Macc.9.14\"></r>)؛ <b>ثبات، رسوخ</b>: <g>τ. πίστεως</g>: <r v=\"Col.2.5\"></r>؛ </s> <s n=\"(b)\">في السبعينية: قبة السماء (التي ظُنّ أنها غطاء صلب): <b>الجَلَد</b>.†</s>","en":"<f><o>στερέωμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στερεόω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.1.6\"></r> ff., <r v=\"Ps.19.1\"></r> <r v=\"Ps.150.1\"></r>, <r v=\"Ezek.1.22-Ezek.1.26\"></r> <r v=\"Ezek.10.1\"></r> <r v=\"Ezek.13.5\"></r>, Da LXX, TH 3:(56), 12:3 (<h n=\"H7549\">רָקִיעַ</h>), <r v=\"Deut.33.26\"></r> (<h n=\"H7834\">שׁחק</h>), <r v=\"Ps.18.2\"></r> <r v=\"Ps.71.3\"></r> (<h n=\"H5553\">סֶלַע</h>), Es 9:29, <r v=\"1Esd.8.82\"></r>, <r v=\"Sir.43.1\"></r>, <r v=\"Sir.43.8\"></r>, <r v=\"1Macc.9.14\"></r> * ;] </e> </et> <s><b>a solid body</b>; </s> <s n=\"(a)\"><b>a support, foundation</b> (Arist., al.); metaph., <b>strength</b> (<r v=\"Ps.17.1-Ps.17.15\"></r> <r v=\"Ps.70.1-Ps.70.5\"></r>, <r v=\"1Macc.9.14\"></r>); <b>steadfastness, firmness</b>: <g>τ. πίστεως</g>, <r v=\"Col.2.5\"></r>; </s> <s n=\"(b)\">the dome of heaven (believed to be a solid canopy), <b>the firmament</b> (LXX).†</s>"},"G4731":{"l":"στερεός","o":4,"ar":"<f><o>στερεός</o>، <g>-ά, -όν </g></f> <s><b>صُلب، راسخ، متين</b>: <g>τροψή</g>: <r v=\"Heb.5.12\"></r>، <r v=\"Heb.5.14\"></r>؛ <g>θεμέλιος</g>، مجازيًا: <r v=\"2Tim.2.19\"></r>. مجازيًا، </s> <s n=\"(a)\">في اليونانية الكلاسيكية: بالمعنى السيئ: <b>قاسٍ، عنيف</b>؛ </s> <s n=\"(b)\">بالمعنى الحسن: <b>ثابت، راسخ</b>: <g>τ. πίστει</g>: <r v=\"1Pet.5.9\"></r>.†</s>","en":"<f><o>στερεός</o>, <g>-ά, -όν </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Num.8.4\"></r> (<h n=\"H4749\">מִקְשָׁה</h>); <g>σ. πέτρα</g>, <r v=\"Isa.5.28\"></r> (<h n=\"H6862\">צַר</h>), etc. ;] </e> </et> <s><b>hard, firm, solid</b>: <g>τροψή</g>, <r v=\"Heb.5.12\"></r>, <r v=\"Heb.5.14\"></r>; <g>θεμέλιος</g>, fig., <r v=\"2Tim.2.19\"></r>. Metaph., </s> <s n=\"(a)\">in bad sense, <b>hard, cruel</b> (Hom., al.); </s> <s n=\"(b)\">in good sense, <b>steadfast, firm</b>: <g>τ. πίστει</g>, <r v=\"1Pet.5.9\"></r>.†</s>"},"G4758":{"l":"στρατολογέω","o":1,"ar":"<f>*† <o>στρατολογέω</o>، <g>-ῶ</g></f> <s><b>جنّد جندًا، جمع جنودًا</b>: <r v=\"2Tim.2.4\"></r>.†</s>","en":"<f>*† <o>στρατολογέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>στρατός</g>, <x><g>λέγω</g></x>), </e> </et> <s><b>to levy a troop, enlist soldiers</b>: <r v=\"2Tim.2.4\"></r> (Diod., Plut., al.).†</s>"},"G4777":{"l":"συνκακοπαθέω","o":2,"ar":"<f>*† <o>συν-κακοπαθέω</o>، <g>-ῶ</g>، </f> <s><b>احتمل المشقّات مع غيره، شارك في احتمال الآلام</b>: <r v=\"2Tim.2.3\"></r>؛ مع قابل المنفعة، <g>τ. εὐαγγελίῳ</g>، <r v=\"2Tim.1.18\"></r>.†</s>","en":"<f>*† <o>συν-κακοπαθέω</o> (Rec. <g>συγκ-</g>), <g>-ῶ</g>, </f> <s><b>to bear evil treatment along with, take one's share of ill-treatment</b>: <r v=\"2Tim.2.3\"></r>; c. dat. commod., <g>τ. εὐαγγελίῳ</g>, <r v=\"2Tim.1.18\"></r>.†</s>"},"G4723":{"l":"στεῖρος","o":5,"ar":"<f><o>στεῖρος</o>، <g>-ον </g> وأيضًا <g>-α, -ον</g>، </f> <s><b>عاقر</b>: عن المرأة، <r v=\"Luke.1.7\"></r>، <r v=\"Luke.1.36\"></r>، <r v=\"Luke.23.29\"></r>، <r v=\"Gal.4.27\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>στεῖρος</o>, <g>-ον </g> also <g>-α, -ον</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6135\">עֲקֶרֶת</h>, <h n=\"H6135\">עֲקָרָה</h> ;] </e> </et> <s><b>barren</b>: of a woman, <r v=\"Luke.1.7\"></r>, <r v=\"Luke.1.36\"></r> <r v=\"Luke.23.29\"></r>, <r v=\"Gal.4.27\"></r> <i>(LXX)</i>.†</s>"},"G4717":{"l":"σταυρόω","o":46,"ar":"<f><o>σταυρόω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>سيّج بالأوتاد، أقام سياجًا</b> (في اليونانية الكلاسيكية). </s> <s n=\"2.\">عند الكتّاب المتأخرين (وإن كان <g>ἀνασταυρόω</g> أكثر شيوعًا): <b>صلب</b>: مع المنصوب للشخص، <r v=\"Matt.20.19\"></r> <r v=\"Matt.23.34\"></r> <r v=\"Matt.26.2\"></r> <r v=\"Matt.27.22\"></r> وما يليه <r v=\"Matt.28.5\"></r>، <r v=\"Mark.15.16\"></r> وما يليه <r v=\"Mark.16.6\"></r>، <r v=\"Luke.23.21\"></r>، <r v=\"Luke.23.23\"></r>، <r v=\"Luke.23.33\"></r> <r v=\"Luke.24.7\"></r>، <r v=\"Luke.24.20\"></r>، <r v=\"John.19.6\"></r> وما يليه، <r v=\"Acts.2.36\"></r> <r v=\"Acts.4.10\"></r>، <r v=\"1Cor.1.13\"></r>، <r v=\"1Cor.1.23\"></r> <r v=\"1Cor.2.2\"></r>، <r v=\"1Cor.2.8\"></r>، <r v=\"2Cor.13.4\"></r>، <r v=\"Gal.3.1\"></r>، <r v=\"Rev.11.8\"></r>؛ مجازيًا، <r v=\"Gal.5.24\"></r> <r v=\"Gal.6.14\"></r>.†</s>","en":"<f><o>σταυρόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σταυρός</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Esth.7.9\"></r> (<h n=\"H8518\">תּלה</h>), <r v=\"Esth.8.13\"></r> * ;]</e> </et> <s n=\"1.\"><b>to fence with pales, impalisade</b> (Thuc.). </s> <s n=\"2.\">In late writers (Polyb., FlJ; but <g>ἀνασταυρόω</g> is more common) <b>to crucify</b>: c. acc. pers., <r v=\"Matt.20.19\"></r> <r v=\"Matt.23.34\"></r> <r v=\"Matt.26.2\"></r> <r v=\"Matt.27.22\"></r> ff. <r v=\"Matt.28.5\"></r>, <r v=\"Mark.15.16\"></r> ff. <r v=\"Mark.16.6\"></r>, <r v=\"Luke.23.21\"></r>, <r v=\"Luke.23.23\"></r>, <r v=\"Luke.23.33\"></r> <r v=\"Luke.24.7\"></r>, <r v=\"Luke.24.20\"></r>, <r v=\"John.19.6\"></r> ff., <r v=\"Acts.2.36\"></r> <r v=\"Acts.4.10\"></r>, <r v=\"1Cor.1.13\"></r>, <r v=\"1Cor.1.23\"></r> <r v=\"1Cor.2.2\"></r>, <r v=\"1Cor.2.8\"></r>, <r v=\"2Cor.13.4\"></r>, <r v=\"Gal.3.1\"></r>, <r v=\"Rev.11.8\"></r>; metaph., <r v=\"Gal.5.24\"></r> <r v=\"Gal.6.14\"></r>.†</s>"},"G4709":{"l":"σπουδαίως","o":4,"ar":"<f>** <o>σπουδαίως</o></f> ظرف <s n=\"1.\"><b>بعجلة</b> أو <b>بغيرة</b>، أي <b>باجتهاد، بغيرة، بحرص</b>: <r v=\"Luke.7.4\"></r>، <r v=\"2Tim.1.17\"></r>، <r v=\"Titus.3.13\"></r>؛ صيغة التفضيل، <g>-οτέρως</g>، <r v=\"Phil.2.28\"></r> (لكن انظر أدناه) </s> <s n=\"2.\"><b>بسرعة، على عجل</b>: صيغة التفضيل، <g>-οτέρως</g>، <r v=\"Phil.2.28\"></r> (لكن انظر أعلاه).†</s>","en":"<f>** <o>σπουδαίως</o></f> adv. <et> <e t=\"derivation\">(&lt; <x><g>σπουδαῖος</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.2.6\"></r> * ;]</e> </et> <s n=\"1.\"><b>with haste</b> or <b>zeal</b>, i.e. <b>earnestly, zealously, diligently</b>: <r v=\"Luke.7.4\"></r>, <r v=\"2Tim.1.17\"></r>, <r v=\"Titus.3.13\"></r>; compar., <g>-οτέρως</g>, <r v=\"Phil.2.28\"></r> (RV, Lft., Weymouth, al., but v. infr.) </s> <s n=\"2.\"><b>hastily, speedily</b>: compar., <g>-οτέρως</g>, <r v=\"Phil.2.28\"></r> (Thayer, Zorell, s.v.; <i>ICC</i>, in l., al., but v. supr.).†</s>"},"G4752":{"l":"στρατεία","o":2,"ar":"<f><o>στρατεία</o>، <g>-ας, ἡ</g> </f> <s><b>حملة عسكرية، غزوة، حرب، محاربة</b>: مجازيًا، <r v=\"2Cor.10.4\"></r>، <r v=\"1Tim.1.18\"></r>.†</s>","en":"<f><o>στρατεία</o> (on the orthogr., v. Deiss., <i>BS</i>, 181 f.), <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>στρατεύω</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6635\">צָבָא</h> ;] </e> </et> <s><b>an expedition, a campaign, warfare</b>: metaph., <r v=\"2Cor.10.4\"></r> (<g>-τιά</g>, T), <r v=\"1Tim.1.18\"></r>.†</s>"},"G4773":{"l":"συγγενεύς","o":12,"ar":"<f>**† <o>συγγενεύς</o>، انظر تحت مدخل <g>συγγενής</g>.</f>","en":"<f>**† <o>συγγενεύς</o>, v.s. <g>συγγενής</g>.</f>"},"G4712":{"l":"στάδιον","o":1,"ar":"<f><o>στάδιον</o>، <g>-ου, τό </g> الجمع، <g>στάδια</g> (قارن <r v=\"John.6.19\"></r>)، وبجمع من صيغة أخرى، <g>στάδιοι</g>، </f> <s><b>غَلْوة (ستاديون)</b>، أي </s> <s n=\"1.\">مقياس للطول = 600 قدم يونانية أو 1⁄8 الميل الروماني <r v=\"Matt.14.24\"></r>، <r v=\"Luke.24.13\"></r>، <r v=\"John.6.19\"></r> <r v=\"John.11.18\"></r>، <r v=\"Rev.14.20\"></r> <r v=\"Rev.21.16\"></r>، ولأن هذا هو طول ميدان السباق الأولمبي: </s> <s n=\"2.\">ميدان السباق: <r v=\"1Cor.9.24\"></r>.†</s>","en":"<f><o>στάδιον</o>, <g>-ου, τό </g> pl., <g>στάδια</g> (<r v=\"John.6.19\"></r>, T), and metapl., <g>στάδιοι</g> (v. B1., § 9, 1), </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.4.9\"></r>, <r v=\"Sus.1.37\"></r>, <r v=\"2Macc.11.5\"></r> <r v=\"2Macc.12.9\"></r> ff. * ;] </e> </et> <s><b>a stadium</b>, i.e. </s> <s n=\"1.\">a measure of length = 600 Greek feet or 1⁄8 of a Roman mile <r v=\"Matt.14.24\"></r> (Rec., WH, txt., R, mg.), <r v=\"Luke.24.13\"></r>, <r v=\"John.6.19\"></r> <r v=\"John.11.18\"></r>, <r v=\"Rev.14.20\"></r> <r v=\"Rev.21.16\"></r>, and, this being the length of the Olympic course, </s> <s n=\"2.\">a race-course: <r v=\"1Cor.9.24\"></r>.†</s>"},"G4793":{"l":"συνκρίνω","o":3,"ar":"<f><o>συν-κρίνω</o></f> <s n=\"1.\"><b>ركّب، قرن (ضمّ معًا)</b>: <r v=\"1Cor.2.13\"></r>. </s> <s n=\"2.\">عند الكتّاب المتأخرين (<r v=\"Wis.7.29\"></r>، وفي مواضع أخرى) = <x><g>παραβάλλω</g></x>، <b>قارن</b>: <r v=\"1Cor.2.13\"></r>، <r v=\"2Cor.10.12\"></r> </s> <s n=\"3.\">في السبعينية، عن الأحلام، <b>فسّر</b> (<r v=\"Gen.40.8\"></r>)، <r v=\"1Cor.2.13\"></r>.†</s>","en":"<f><o>συν-κρίνω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>)</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6622\">פּתר</h> ;] </e> </et> <s n=\"1.\"><b>to compound, combine</b>: <r v=\"1Cor.2.13\"></r>, R, mg.<i>1</i> (Lft., <i>Notes</i>, 180 f.). </s> <s n=\"2.\">In Arist. and later writers (<r v=\"Wis.7.29\"></r>, al.) = <x><g>παραβάλλω</g></x>, <b>to compare</b>: <r v=\"1Cor.2.13\"></r>, R, txt. (Field, <i>Notes</i>, 168), <r v=\"2Cor.10.12\"></r> </s> <s n=\"3.\">In LXX, of dreams, <b>to interpret</b> (<r v=\"Gen.40.8\"></r>, <r v=\"1Cor.2.13\"></r>, R, mg.<i>2</i> (but v. reff. supr.).†</s>"},"G4727":{"l":"στενάζω","o":6,"ar":"<f><o>στενάζω </o></f> <s><b>يئنّ، يتنهّد</b> («والكلمة تدل على شعور داخلي غير معبَّر عنه»): <r v=\"Mark.7.34\"></r>، <r v=\"2Cor.5.2\"></r>، <r v=\"2Cor.5.4\"></r>، <r v=\"Heb.13.17\"></r>، <r v=\"Jas.5.9\"></r> (وفي الترجمات الإنجليزية: <b>يتذمّر</b>)؛ <g>ἐν ἑαυτοῖς</g> (في أنفسنا)، <r v=\"Rom.8.23\"></r> (قارن <g>ἀνα-</g>، <g>συ(ν)-στενάζω</g>).†</s>","en":"<f><o>στενάζω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H584\">אנח</h> ni., <h n=\"H602\">אנק</h>, etc. ;] </e> </et> <s><b>to groan</b> (\"the word denotes feeling which is internal and unexpressed,\" Mayor, <i>Ja.</i>, 162): <r v=\"Mark.7.34\"></r>, <r v=\"2Cor.5.2\"></r>, <r v=\"2Cor.5.4\"></r>, <r v=\"Heb.13.17\"></r>, <r v=\"Jas.5.9\"></r> (EV, <b>murmur</b>); <g>ἐν ἑαυτοῖς</g>, <r v=\"Rom.8.23\"></r> (cf. <g>ἀνα-</g>, <g>συ(ν)-στενάζω</g>).†</s> <sy><i>SYN.</i>: v.s. <x><g>κλαίω</g></x> </sy>"},"G4729":{"l":"στενοχωρέω","o":3,"ar":"<f><o>στενο-χωρέω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>يكون في ضيق</b> (قارن <r v=\"Isa.49.19\"></r>)؛ ومجازيًا، في اليونانية الكلاسيكية: <b>يكون قلقًا</b>. </s> <s n=\"2.\">عند الكتّاب المتأخرين، متعدّيًا: <b>يضيّق على، يحصر</b> (وفي السبعينية): في المبني للمجهول، مجازيًا، <r v=\"2Cor.4.8\"></r>، <r v=\"2Cor.6.12\"></r>.†</s>","en":"<f><o>στενο-χωρέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στενός</g></x> + <x><g>χῶρος</g></x>, <b>space</b>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Josh.17.15\"></r> (<h n=\"H213\">אוּץ</h>), <r v=\"Judg.16.16\"></r> (<h n=\"H509\">אלץ</h> pi.), <r v=\"Isa.28.19\"></r> (<h n=\"H7114\">קצר</h>) <r v=\"Isa.49.19\"></r> (<h n=\"H6887\">צרר</h>), <r v=\"4Macc.11.11\"></r> * ;] </e> </et> <s n=\"1.\"><b>to be straitened</b> (cf. <r v=\"Isa.49.19\"></r>); metaph., <b>to be anxious</b> (Hipp., al.). </s> <s n=\"2.\">In late writers, trans., <b>to straiten, compress</b> (LXX, Diod., al.; <g>π.</g> ap. MM, xxiii): pass., trop., <r v=\"2Cor.4.8\"></r> <r v=\"2Cor.6.12\"></r>.†</s>"},"G4722":{"l":"στέγω","o":4,"ar":"<f>** <o>στέγω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: أصلاً: <b>غطّى بإحكام، حمى بالتغطية</b>، خاصةً لمنع دخول الماء أو خروجه. </s> <s n=\"2.\"><b>غطّى، كتم، ستر</b> (<r v=\"Sir.8.17\"></r>): <r v=\"1Cor.13.7\"></r>. </s> <s n=\"3.\">بالتغطية: <b>صدّ، احتمل، صبر على</b>: <r v=\"1Cor.9.12\"></r>، <r v=\"1Cor.13.7\"></r>، <r v=\"1Thess.3.1\"></r>، <r v=\"1Thess.3.5\"></r>.†</s>","en":"<f>** <o>στέγω</o></f> <et> <e t=\"derivation\">(cf. Lat. <l>tego</l>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.8.17\"></r> * ;] </e> </et> <s n=\"1.\">prop., <b>to cover closely, to protect by covering</b>, esp. to keep water in or out (Soph., Plat., al.). </s> <s n=\"2.\"><b>to cover, keep secret, conceal</b> (<r v=\"Sir.8.17\"></r>, Polyb., al.): <r v=\"1Cor.13.7\"></r>, R, mg. </s> <s n=\"3.\">By covering <b>to ward of, bear up under, endure</b> (for exx., v., Lft., <i>Notes</i>, 40; M, <i>Th.</i>, 36): <r v=\"1Cor.9.12\"></r> <r v=\"1Cor.13.7\"></r>, <r v=\"1Thess.3.1\"></r>, <r v=\"1Thess.3.5\"></r>.†</s>"},"G4703":{"l":"σπόρος","o":6,"ar":"<f><o>σπόρος</o>، <g>-ου, ὁ</g></f> <s>= <g>σπορά</g>، </s> <s n=\"1.\"><b>زرع</b> أو <b>وقت الزرع</b>. </s> <s n=\"2.\"><b>بذار</b> مزروع (وهو المعتاد في اليونانية المتأخرة): <r v=\"Mark.4.26-Mark.4.27\"></r>، <r v=\"Luke.8.5\"></r>، <r v=\"Luke.8.11\"></r>، <r v=\"2Cor.9.10\"></r>؛ مجازيًا، عن الصدقة: <r v=\"2Cor.9.10\"></r>.†</s>","en":"<f><o>σπόρος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σπείρω</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2233\">זֶרַע</h> ;] </e> </et> <s>= <g>σπορά</g>, </s> <s n=\"1.\"><b>sowing</b> or <b>seedtime</b>. </s> <s n=\"2.\"><b>seed</b> sown (so usually in late Gk.): <r v=\"Mark.4.26-Mark.4.27\"></r>, <r v=\"Luke.8.5\"></r>, <r v=\"Luke.8.11\"></r>, <r v=\"2Cor.9.10\"></r> a (LTr.); metaph., of almsgiving, <r v=\"2Cor.9.10\"></r> .†</s>"},"G4786":{"l":"συνκεράννυμι","o":2,"ar":"<f><o>συν-κεράννυμι</o></f> <s><b>يمزج أو يخلط معًا، يركّب</b>: مع المنصوب، <r v=\"1Cor.12.24\"></r>؛ اسم المفعول التام المبني للمجهول، <r v=\"Heb.4.2\"></r> (في إحدى القراءتين)؛ ونفسه عن الأشخاص مع القابل للأداة: <b>يتّحد بـ، يتّفق مع</b>، في الموضع نفسه (في القراءة الأخرى).†</s>","en":"<f><o>συν-κεράννυμι</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.2.43\"></r> (<h n=\"H6151\">עֲרַב</h> ithpa.), <r v=\"2Macc.15.39\"></r> * ;]</e> </et> <s><b>to mix or blend together, compound</b>: c. acc., <r v=\"1Cor.12.24\"></r>; ptcp. pf. pass., <r v=\"Heb.4.2\"></r>, T, WH, mg., R, mg.; id., of persons, c. dat. instr., <b>to be united with, agree with</b>, ib., WH, txt., R, txt. (v. Westc., in l.).†</s>"},"G4737":{"l":"στεφανόω","o":3,"ar":"<f><o>στεφανόω</o>، <g>-ῶ</g></f> <s>مع المنصوب للشخص، </s> <s><b>يكلِّل</b>: عن المنتصر، <r v=\"2Tim.2.5\"></r>. مجازيًا، <g>δόξῃ κ. τιμῇ</g>، <r v=\"Heb.2.7\"></r>، <r v=\"Heb.2.9\"></r> (السبعينية).†</s>","en":"<f><o>στεφανόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στέφανος</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5849\">עטר</h> ;] </e> </et> <s>c. acc. pers., </s> <s><b>to crown</b>: of a victor, <r v=\"2Tim.2.5\"></r>. Metaph., <g>δόξῃ κ. τιμῇ</g>, <r v=\"Heb.2.7\"></r>, <r v=\"Heb.2.9\"></r> (LXX).†</s>"},"G4734":{"l":"Στεφανᾶς","o":3,"ar":"<f><o>Στεφανᾶς</o>، <g>-ᾶ, ὁ </g></f> <s><b>استفاناس</b>: <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.16.15\"></r>، <r v=\"1Cor.16.17\"></r>.†</s>","en":"<f><o>Στεφανᾶς</o>, <g>-ᾶ, ὁ </g></f> <s><b>Stephanas</b>: <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.16.15\"></r>, <r v=\"1Cor.16.17\"></r>.†</s>"},"G4735":{"l":"στέφανος","o":18,"ar":"<f><o>στέφανος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ما يحيط أو يطوّق</b> (كالسور أو الجمع من الناس). </s> <s n=\"2.\"><b>إكليل</b>، أي الإكليل أو الطوق الذي يُعطى جائزةً للنصر، أو زينةً في الأعياد، أو تكريمًا عامًا لخدمة متميزة أو فضل شخصي (ويُقدَّم كذلك للملوك، خاصةً بمناسبة <g>παρουσία</g>، انظره؛ وعن استعماله في السبعينية للتاج الذهبي الملكي، وهو أصلاً <g>διάδημα</g>، انظره، قارن <r v=\"Jas.1.12\"></r>): <r v=\"Matt.27.29\"></r>، <r v=\"Mark.15.17\"></r>، <r v=\"John.19.2\"></r>، <r v=\"John.19.5\"></r>، <r v=\"1Cor.9.25\"></r>، <r v=\"Rev.4.4\"></r>، <r v=\"Rev.4.10\"></r> <r v=\"Rev.6.2\"></r> <r v=\"Rev.9.7\"></r> <r v=\"Rev.12.1\"></r> <r v=\"Rev.14.14\"></r>. مجازيًا: <r v=\"Phil.4.1\"></r>، <r v=\"Rev.3.11\"></r>؛ <g>τ. δικαιοσύνης</g>، <r v=\"2Tim.4.8\"></r>؛ <g>τ. δόξης</g>، <r v=\"1Pet.5.4\"></r>؛ <g>καυχήσεως</g>، <r v=\"1Thess.2.19\"></r>؛ <g>τ. ζωῆς</g> (المضاف إليه للبدل)، <r v=\"Jas.1.12\"></r>، <r v=\"Rev.2.10\"></r>.†</s>","en":"<f><o>στέφανος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>στέφω</g>, <b>to encircle</b>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5850\">עֲטָרָה</h> ;]</e> </et> <s n=\"1.\"><b>that which surrounds or encompasses</b> (as a wall, a crowd: Hom., al.). </s> <s n=\"2.\"><b>a crown</b>, i.e. the wreath, garland or chaplet given as a prize for victory, as a festal ornament, or as a public honour for disting­uished service or personal worth (so to sovereigns, especially on the occasion of a <g>παρουσία</g>, q.v.; cf. Deiss., <i>LAE</i>, 372 ff.; on its use in LXX for the golden crown of royalty (prop., <g>διάδημα</g>, q.v., cf. Hort and Mayor on <r v=\"Jas.1.12\"></r>): <r v=\"Matt.27.29\"></r>, <r v=\"Mark.15.17\"></r>, <r v=\"John.19.2\"></r>, <r v=\"John.19.5\"></r>, <r v=\"1Cor.9.25\"></r>, <r v=\"Rev.4.4\"></r>, <r v=\"Rev.4.10\"></r> <r v=\"Rev.6.2\"></r> <r v=\"Rev.9.7\"></r> <r v=\"Rev.12.1\"></r> <r v=\"Rev.14.14\"></r>. Metaph.: <r v=\"Phil.4.1\"></r>, <r v=\"Rev.3.11\"></r>; <g>τ. δικαιοσύνης</g> (cf. Deiss., <i>LAE</i>, 312), <r v=\"2Tim.4.8\"></r>; <g>τ. δόξης</g>, <r v=\"1Pet.5.4\"></r>; <g>καυχήσεως</g>, <r v=\"1Thess.2.19\"></r> (v. M, <i>Th.</i>, in l.); <g>τ. ζωῆς</g> (gen. appos.), <r v=\"Jas.1.12\"></r>, <r v=\"Rev.2.10\"></r>.†</s>"},"G4747":{"l":"στοιχεῖον","o":6,"ar":"<f>** <o>στοιχεῖον</o>، <g>-ου, τό </g></f> <s>أصلاً: <b>واحد في صفّ</b> (<g>στοῖχος</g>) أو <b>سلسلة</b>، ومن ثمّ: </s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>خط الظل في المِزْوَلة</b>. </s> <s n=\"2.\">في اليونانية الكلاسيكية: <b>صوت أوّلي</b> أو <b>حرف</b> من حروف الهجاء. </s> <s n=\"3.\"><b>مبادئ</b> أو <b>أركان</b> المعرفة الأولى: <r v=\"Heb.5.12\"></r>؛ <g>πτωχὰ σ.</g>، <r v=\"Gal.4.9\"></r>؛ <g>σ. τοῦ κόσμου</g>، <r v=\"Gal.4.3\"></r>، <r v=\"Col.2.8\"></r>، <r v=\"Col.2.20\"></r> (ولكن انظر أدناه). </s> <s n=\"4.\"><b>العناصر</b> المادية للكون (وكذلك في السبعينية): <r v=\"2Pet.3.10\"></r>، <r v=\"2Pet.3.12\"></r>. </s> <s n=\"5.\">عند الكتّاب المتأخرين: <b>الأجرام السماوية</b>. </s> <s n=\"6.\"><b>الأرواح</b> أو <b>الأرواح الحارسة</b> للطبيعة (في الكتابات اليهودية المتأخرة؛ ولهذا المعنى في <r v=\"Gal.4.9\"></r> وفي كولوسي في المواضع المذكورة، قارن <r v=\"Col.2.8\"></r>).†</s>","en":"<f>** <o>στοιχεῖον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.7.17\"></r> <r v=\"Wis.19.18\"></r>, <r v=\"4Macc.12.13\"></r> * ;] </e> </et> <s>prop., <b>one of a row</b> (<g>στοῖχος</g>) or <b>series</b>, hence, </s> <s n=\"1.\"><b>the shadow-line of a dial</b> (Aristoph.). </s> <s n=\"2.\"><b>an elementary sound</b> or <b>letter</b> of the alphabet (Anth., Plut., <g>π.</g>). </s> <s n=\"3.\"><b>the elements</b> or <b>rudiments</b> of knowledge (Arist., al.) <r v=\"Heb.5.12\"></r>; <g>πτωχὰ σ.</g>, <r v=\"Gal.4.9\"></r>; <g>σ. τοῦ κόσμου</g>, <r v=\"Gal.4.3\"></r>, <r v=\"Col.2.8\"></r>, <r v=\"Col.2.20\"></r> (but v. infr.). </s> <s n=\"4.\">The material <b>elements</b> of the universe (Plat.; LXX, ll. c.): <r v=\"2Pet.3.10\"></r>, <r v=\"2Pet.3.12\"></r>. </s> <s n=\"5.\">The <b>heavenly bodies</b> (Diog. Laert.). </s> <s n=\"6.\">The <b>demons</b> or <b>tutelary spirits</b> of nature (Enoch., Test., Sol., al.; for this sense in <r v=\"Gal.4.9\"></r>, Col, ll. c., v. <i>ICC</i> on <r v=\"Col.2.8\"></r>; <i>Enc. Bibl.</i>, s.v. \" Elements \").†</s>"},"G4724":{"l":"στέλλω","o":2,"ar":"<f><o>στέλλω </o></f> <s n=\"1.\">أصلاً: <b>وضع، أقام، رتّب، جهّز</b>؛ ومن ثمّ<b>، في الصيغة الوسطى: تهيّأ لـ، استعدّ</b> (<r v=\"Wis.7.14\"></r>، <r v=\"2Macc.5.1\"></r>). </s> <s n=\"2.\"><b>جمع، لَمّ</b> (كطيّ الأشرعة)، ومن ثمّ <b>كبح، ردع</b>؛ وفي الصيغة الوسطى: <b>امتنع</b> أو <b>انسحب، تجنّب، ابتعد عن</b>: <r v=\"2Cor.8.20\"></r>؛ يليه <g>ἀπό</g>، <r v=\"2Thess.3.6\"></r> </s> <s>(قارن <g>ἀπο-</g>، <g>ἐξ-απο-</g>، <g>συν-απο-</g>، <g>δια-</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>συ(ν)-</g>، <g>ὑπο-στέλλω</g>).†</s>","en":"<f><o>στέλλω </o></f> <et> <e t=\"septuagint\">[in LXX (mid.): <r v=\"Mal.2.5\"></r> (<h n=\"H2865\">חתת</h> ni.), <r v=\"Prov.31.24\"></r>, <r v=\"Wis.7.14\"></r> <r v=\"Wis.14.1\"></r>, <r v=\"2Macc.5.1\"></r>, <r v=\"3Macc.1.19\"></r> <r v=\"3Macc.4.11\"></r> * ;] </e> </et> <s n=\"1.\">prop., <b>to set, place, arrange, fit out</b>; hence<b>, mid., to set oneself for, prepare</b> (<r v=\"Wis.7.14\"></r>, <r v=\"2Macc.5.1\"></r>). </s> <s n=\"2.\"><b>to bring together, gather up</b> (in Hom. of furling sails), hence <b>to restrain, check</b>; mid., <b>to restrain</b> or <b>withdraw oneself, hold aloof, avoid</b>: <r v=\"2Cor.8.20\"></r>; seq. <g>ἀπό</g>, <r v=\"2Thess.3.6\"></r> </s> <s>(cf. <g>ἀπο-</g>, <g>ἐξ-απο-</g>, <g>συν-απο-</g>, <g>δια-</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>συ(ν)-</g>, <g>ὑπο-στέλλω</g>).†</s>"},"G4788":{"l":"συνκλείω","o":4,"ar":"<f><o>συν-κλείω</o></f> <s><b>أغلق على، طوّق، حبس من كل جهة</b>: عن صيد السمك، <r v=\"Luke.5.6\"></r>؛ مجازيًا (<r v=\"Ps.31.9\"></r>، وفي مواضع أخرى)، <r v=\"Rom.11.32\"></r>، <r v=\"Gal.3.22-Gal.3.23\"></r>.†</s>","en":"<f><o>συν-κλείω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5462\">סגר</h>;] </e> </et> <s><b>to shut together, enclose, shut in on all sides</b>: of a catch of fish, <r v=\"Luke.5.6\"></r>; metaph. (<r v=\"Ps.31.9\"></r>, al.), <r v=\"Rom.11.32\"></r>, <r v=\"Gal.3.22-Gal.3.23\"></r>.†</s>"},"G4730":{"l":"στενοχωρία","o":4,"ar":"<f><o>στενοχωρία</o>، <g>-ας, ἡ</g> (انظر أعلاه) </f> <s>في اليونانية الكلاسيكية: <b>ضيق المكان، قلة المتّسع</b>. ومجازيًا (قارن <r v=\"Deut.28.53\"></r>، <r v=\"Wis.5.3\"></r>، وفي مواضع أخرى): <b>ضيق، شدة</b>: <g>θλίψις καὶ</g> (<g>ἢ</g>) <g>σ.</g>، <r v=\"Rom.2.9\"></r> <r v=\"Rom.8.35\"></r> (<b>كرب</b>)؛ وفي الجمع: <r v=\"2Cor.6.4\"></r> <r v=\"2Cor.12.10\"></r>.†</s>","en":"<f><o>στενοχωρία</o>, <g>-ας, ἡ</g> (v. supr.) </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6695\">צוּקָה</h>, etc. ;] </e> </et> <s><b>narrowness of space, want of room</b> (Thuc., al.). Metaph. (Xen., Polyb., <r v=\"Deut.28.53\"></r>, <r v=\"Wis.5.3\"></r>, al.), <b>difficulty, distress</b>: <g>θλίψις καὶ</g> (<g>ἢ</g>) <g>σ.</g>, <r v=\"Rom.2.9\"></r> <r v=\"Rom.8.35\"></r> (EV, <b>anguish</b>); pl. (cf. Bl., § 32, 6; WM, 220), <r v=\"2Cor.6.4\"></r> <r v=\"2Cor.12.10\"></r>.†</s> <sy><i>SYN.</i>: <x><g>θλίψις</g></x>, q.v </sy>"},"G4705":{"l":"σπουδαῖος","o":3,"ar":"<f><o>σπουδαῖος</o>، <g>-α, -ον</g></f> <s><b>مستعجل</b>؛ ومن ثمّ <b>غيور، مشتاق، مجتهد، جادّ</b>: يليه <g>ἐν</g>، <r v=\"2Cor.8.22\"></r>؛ وصيغة التفضيل <g>-οτεροσς</g> <r v=\"2Cor.8.17\"></r> (وهي هنا بمعنى صيغة التفضيل العليا) <r v=\"2Cor.8.22\"></r>.†</s>","en":"<f><o>σπουδαῖος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σπουδή</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.41.25\"></r> * ;]</e> </et> <s><b>in haste</b>; hence, <b>zealous, eager, diligent, earnest</b>: seq. <g>ἐν</g>, <r v=\"2Cor.8.22\"></r>; compar., <g>-οτεροσς</g> <r v=\"2Cor.8.17\"></r> (here in superl. sense, v. Bl., § 44, 3) <r v=\"2Cor.8.22\"></r>.†</s>"},"G4774":{"l":"συνγνώμη","o":1,"ar":"<f>** <o>συν-γνώμη</o>، -ης، ἡ</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>اعتراف</b>. </s> <s n=\"2.\"><b>مشاركة في الشعور</b>؛ ومن ثمّ <b>إذن، سماح</b>: <r v=\"1Cor.7.6\"></r>. </s> <s n=\"3.\">في اليونانية الكلاسيكية: <b>صفح</b>.†</s>","en":"<f>** <o>συν-γνώμη</o> (Rec. <g>συγγ-</g>), -ης, ἡ</f> <et> <e t=\"derivation\">(&lt; <g>συγγιγνώσκω</g>, (a) <b>to agree with</b>; (b) <b>to pardon</b>), </e> <e t=\"septuagint\">[in LXX: Si <i>prol.</i><i>14</i> (B<i>1</i><h>א</h><i>1</i> om.) 313, Mac 14:20* ;] </e> </et> <s n=\"1.\"><b>confession</b>. </s> <s n=\"2.\"><b>fellow feeling</b>; hence, <b>concession, allowance</b>: <r v=\"1Cor.7.6\"></r> (v. <i>ICC</i>, in l.). </s> <s n=\"3.\"><b>pardon</b>.†</s>"},"G4720":{"l":"Στάχυς","o":1,"ar":"<f><o>Στάχυς</o>، <g>-υος, ὁ </g> </f> <s><b>استاخيس</b>: <r v=\"Rom.16.9\"></r>.†</s>","en":"<f><o>Στάχυς</o>, <g>-υος, ὁ </g></f> <s><b>Stachys</b>: <r v=\"Rom.16.9\"></r> (v. Lft., <i>Phl.</i>, 174; MM, xxiii).†</s>"},"G4748":{"l":"στοιχέω","o":5,"ar":"<f><o>στοιχέω</o>، <g>-ῶ</g></f> <s>في اليونانية الكلاسيكية: <b>اصطفّ في صفوف</b> (عن الأمواج والنباتات إلخ، وكذلك عن الناس)، <b>سار في صفّ</b> (خاصةً عن السير في صفوف إلى المعركة). ومجازيًا، عند الكتّاب المتأخرين: <b>سلك بحسب قانون</b>: <r v=\"Acts.21.24\"></r>؛ مع القابل: <b>سلك بحسب</b> أو <b>في</b> (بوصفه قانونًا للحياة)، <r v=\"Rom.4.12\"></r>، <r v=\"Gal.5.25\"></r> <r v=\"Gal.6.16\"></r>، <r v=\"Phil.3.16\"></r> (قارن <g>συν-στοιχέω</g>).†</s>","en":"<f><o>στοιχέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>στοῖχος</g>, a row), </e> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.11.6\"></r> (<h n=\"H3787\">כָּשֵׁר</h>) * ;]</e> </et> <s><b>to be in rows</b> (of waves, plants, etc., as well as of men), <b>to walk in line</b> (esp. of marching in file to battle; Xen., <i>Cyr.</i>, vi, 3, 34, al.). Metaph., in late writers, <b>to walk by rule</b>: <r v=\"Acts.21.24\"></r>; c. dat., <b>to walk by</b> or <b>in</b> (as a rule of life), <r v=\"Rom.4.12\"></r> (cf. MM, xxiii), <r v=\"Gal.5.25\"></r> <r v=\"Gal.6.16\"></r>, <r v=\"Phil.3.16\"></r> (cf. <g>συν-στοιχέω</g>).†</s>"},"G4781":{"l":"συνκάμπτω","o":1,"ar":"<f><o>συν-κάμπτω</o></f> <s><b>حنى تمامًا، أحنى</b>: <g>τ. νῶτον</g>، مجازيًا، <r v=\"Rom.11.10\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>συν-κάμπτω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.68.10\"></r>, <r v=\"Ps.68.23\"></r>(<h n=\"H4571\">מעד</h>hi.), etc. ;] </e> </et> <s><b>to bend completely, bend together</b>: <g>τ. νῶτον</g>, fig., <r v=\"Rom.11.10\"></r> <i>(LXX)</i>.†</s>"},"G4751":{"l":"στόμαχος","o":1,"ar":"<f>* <o>στόμαχος</o>، <g>-ου, ὁ</g></f> <s>بالمعنى الأصلي، <b>فم، فتحة</b>؛ </s> <s n=\"(a)\">في اليونانية الكلاسيكية: <b>الحلق</b>؛ </s> <s n=\"(b)\">في اليونانية الكلاسيكية: عن فم المعدة؛ </s> <s n=\"(c)\">عند الكتّاب المتأخرين (وفي العهد الجديد): <b>المعدة</b>: <r v=\"1Tim.5.23\"></r>.†</s>","en":"<f>* <o>στόμαχος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στόμα</g></x>), </e> </et> <s>prop., <b>a mouth, an opening</b>; </s> <s n=\"(a)\">in early Gk. writers, <b>the throat</b>; </s> <s n=\"(b)\">of the opening of the stomach (Arist.); </s> <s n=\"(c)\">in later writers (Plut., al.), <b>the stomach</b>: <r v=\"1Tim.5.23\"></r>.†</s>"},"G4796":{"l":"συνχαίρω","o":7,"ar":"<f><o>συν-χαίρω</o></f> <s n=\"1.\"><b>يفرح مع</b>: مع القابل للشخص، <r v=\"Luke.1.58\"></r> <r v=\"Luke.15.6\"></r>، <r v=\"Luke.15.9\"></r>، <r v=\"Phil.2.17-Phil.2.18\"></r>؛ مع القابل للشيء، <r v=\"1Cor.12.26\"></r> <r v=\"1Cor.13.6\"></r>. </s> <s n=\"2.\"><b>يهنّئ</b>: <r v=\"Phil.2.17-Phil.2.18\"></r>.†</s>","en":"<f><o>συν-χαίρω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.21.6\"></r> (<h n=\"H6711\">צחק</h>), <r v=\"3Macc.1.8\"></r> R * ;] </e> </et> <s n=\"1.\"><b>to rejoice with</b>: c. dat pers., <r v=\"Luke.1.58\"></r> <r v=\"Luke.15.6\"></r>, <r v=\"Luke.15.9\"></r>, <r v=\"Phil.2.17-Phil.2.18\"></r>, EV; c. dat. rei, <r v=\"1Cor.12.26\"></r> <r v=\"1Cor.13.6\"></r>. </s> <s n=\"2.\"><b>to congratulate</b> (Æschin., Polyb., al.): <r v=\"Phil.2.17-Phil.2.18\"></r> (Lft., in l.; cf. MM, xxiv).†</s>"},"G4739":{"l":"στήκω","o":9,"ar":"<f>† <o>στήκω </o>، صيغة مضارع متأخرة مشتقة من التام <g>ἕστηκα</g>، </f> <s>= <g>ἵστημι</g>: <b>وقف</b>: <r v=\"Mark.3.31\"></r> <r v=\"Mark.11.25\"></r>، <r v=\"John.1.26\"></r>، <r v=\"Rev.12.4\"></r>. مجازيًا: <b>ثبت، صمد</b>: مطلقًا، <r v=\"Gal.5.1\"></r>، <r v=\"2Thess.2.15\"></r>؛ يليه <g>ἐν</g>، <r v=\"John.8.44\"></r>، <r v=\"1Cor.16.13\"></r>، <r v=\"Phil.1.27\"></r> <r v=\"Phil.4.1\"></r>؛ مع القابل، <r v=\"Rom.14.4\"></r>.†</s>","en":"<f>† <o>στήκω </o> late Pres., formed from perf., <g>ἕστηκα</g> (v. B1., § 17; WH, <i>App.</i>, 169; Kennedy, <i>Sources</i>, 158; M, <i>Pr.</i>, 238; MM, xxiii), </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.14.13\"></r> A, <r v=\"Judg.16.26\"></r> B, <r v=\"1Kgs.8.11\"></r> B * ;]</e> </et> <s>= <g>ἵστημι</g>, <b>to stand</b>: <r v=\"Mark.3.31\"></r> <r v=\"Mark.11.25\"></r>, <r v=\"John.1.26\"></r>, <r v=\"Rev.12.4\"></r> (<g>ἕστηκεν</g> T). Metaph., <b>to stand firm, stand fast</b>: absol., <r v=\"Gal.5.1\"></r> (but v. Field, <i>Notes</i>, 189 f.), <r v=\"2Thess.2.15\"></r>; seq. <g>ἐν</g>, <r v=\"John.8.44\"></r> (<g>ἕστηκεν</g>, T, R, mg.), <r v=\"1Cor.16.13\"></r>, <r v=\"Phil.1.27\"></r> <r v=\"Phil.4.1\"></r>; c. dat., <r v=\"Rom.14.4\"></r>.†</s>"},"G4710":{"l":"σπουδή","o":12,"ar":"<f><o>σπουδή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>عجلة، سرعة</b>: <g>μετὰ σ.</g> (<r v=\"Wis.19.2\"></r>)، <r v=\"Mark.6.25\"></r>، <r v=\"Luke.1.39\"></r>. </s> <s n=\"2.\"><b>غيرة، اجتهاد، جدّية</b>: <r v=\"Rom.12.11\"></r>، <r v=\"2Cor.7.11-2Cor.7.12\"></r> <r v=\"2Cor.8.7-2Cor.8.8\"></r>؛ <g>ἐν σ.</g>، <r v=\"Rom.12.8\"></r>؛ يليه <g>ὑπέρ</g>، <r v=\"2Cor.8.16\"></r>؛ <g>σπουδὴν ἐνδείκνυσθαι</g>، <r v=\"Heb.6.11\"></r>؛ <g>σ. παρεισφέρειν</g>، <r v=\"2Pet.1.5\"></r>؛ <g>πᾶσαν σ. ποιεῖσθαι</g>، <r v=\"Jude.1.3\"></r>.†</s>","en":"<f><o>σπουδή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σπεύδω</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H926\">בּהל</h>, its parts and derivatives ;]</e> </et> <s n=\"1.\"><b>haste, speed</b>: <g>μετὰ σ.</g> (<r v=\"Wis.19.2\"></r>), <r v=\"Mark.6.25\"></r>, <r v=\"Luke.1.39\"></r>. </s> <s n=\"2.\"><b>zeal, diligence, earnestness</b>: <r v=\"Rom.12.11\"></r>, <r v=\"2Cor.7.11-2Cor.7.12\"></r> <r v=\"2Cor.8.7-2Cor.8.8\"></r>; <g>ἐν σ.</g>, <r v=\"Rom.12.8\"></r> (v. M, <i>Pr</i>, 104); seq. <g>ὑπέρ</g>, <r v=\"2Cor.8.16\"></r>; <g>σπουδὴν ἐνδείκνυσθαι</g>, <r v=\"Heb.6.11\"></r>; <g>σ. παρεισφέρειν</g>, <r v=\"2Pet.1.5\"></r>; <g>πᾶσαν σ. ποιεῖσθαι</g>, <r v=\"Jude.1.3\"></r> (v. MM, xxiii; M, <i>Pr.</i>, 214; Deiss., <i>BS</i>, 361, 364).†</s>"},"G4791":{"l":"συνκοινωνός","o":4,"ar":"<f>*† <o>συν-κοινωνός</o>، <g>όν</g>، </f> <s><b>شريك</b>، <b>مشترك مع آخرين في</b>: مع المضاف إليه للشيء، <r v=\"Rom.11.17\"></r>، <r v=\"1Cor.9.23\"></r>؛ ونفسه مع المضاف إليه للأشخاص، <r v=\"Phil.1.7\"></r>؛ يليه <g>ἐν</g>، <r v=\"Rev.1.9\"></r>.†</s>","en":"<f>*† <o>συν-κοινωνός</o> (Rec. <g>συγκ-</g>), <g>όν</g>, </f> <s><b>partaking jointly of</b>: c. gen. rei, <r v=\"Rom.11.17\"></r>, <r v=\"1Cor.9.23\"></r>; id. c. gen. pers., <r v=\"Phil.1.7\"></r>; seq. <g>ἐν</g>, <r v=\"Rev.1.9\"></r>.†</s>"},"G4767":{"l":"στυγητός","o":1,"ar":"<f>* <o>στυγητός</o>، <g>-όν</g></f> <s><b>مبغَض، مكروه</b>: <r v=\"Titus.3.3\"></r>.†</s>","en":"<f>* <o>στυγητός</o>, <g>-όν</g></f> <et> <e t=\"derivation\">(&lt; <g>στυγέω</g>, <b>to hate</b>), </e> </et> <s><b>hated, hateful</b>: <r v=\"Titus.3.3\"></r>.†</s>"},"G4714":{"l":"στάσις","o":9,"ar":"<f><o>στάσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>وقوف، موضع، مكانة</b>: <g>σ. ἔχειν</g> (قارن اللاتينية <l>locum habere</l>)، <r v=\"Heb.9.8\"></r>. </s> <s n=\"2.\"><b>فتنة، عصيان</b>: <r v=\"Mark.15.7\"></r>، <r v=\"Luke.23.19\"></r>، <r v=\"Luke.23.25\"></r>، <r v=\"Acts.19.40\"></r> <r v=\"Acts.24.5\"></r>. </s> <s n=\"3.\"><b>منازعة، خلاف</b>: <r v=\"Acts.15.2\"></r> <r v=\"Acts.23.7\"></r>، <r v=\"Acts.23.10\"></r>.†</s>","en":"<f><o>στάσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἵστημι</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5975\">עמד</h>, its parts and derivatives, also for <h n=\"H7378\">רִיב</h> (<r v=\"Prov.17.14\"></r>), etc. (v. Deiss., <i>BS</i>, 158 f.) ;]</e> </et> <s n=\"1.\"><b>a standing, place, status</b>: <g>σ. ἔχειν</g> (Polyb., v, 5, 3; and cf. Lat. <l>locum habere</l>), <r v=\"Heb.9.8\"></r>. </s> <s n=\"2.\"><b>insurrection, sedition</b>: <r v=\"Mark.15.7\"></r>, <r v=\"Luke.23.19\"></r>, <r v=\"Luke.23.25\"></r>, <r v=\"Acts.19.40\"></r> <r v=\"Acts.24.5\"></r>. </s> <s n=\"3.\">In poets and late prose, <b>strife, dissension</b> (cf. MM, xxiii) <r v=\"Acts.15.2\"></r> <r v=\"Acts.23.7\"></r>, <r v=\"Acts.23.10\"></r>.†</s>"},"G4764":{"l":"στρῆνος","o":1,"ar":"<f><o>στρῆνος</o>، <g>-ους, τό</g></f> <s><b>تنعّم متعجرف، بطر، ترف</b>: <r v=\"Rev.18.3\"></r> (وهي كلمة متأخرة؛ قارن <g>στρηνιάω</g>).†</s>","en":"<f><o>στρῆνος</o>, <g>-ους, τό</g></f> <et> <e t=\"derivation\">(cf. Lat. <l>strenuus</l>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.19.28\"></r> (<h n=\"H7600\">שַׁאֲנָן</h>)* ;]</e> </et> <s><b>insolent luxury, wantonness</b>: <r v=\"Rev.18.3\"></r> (a late word, first found in a Comic poet, <i>B.C.</i> 300, v. Kennedy, <i>Sources</i>, 41, cf. <g>στρηνιάω</g>).†</s>"},"G4718":{"l":"σταφυλή","o":3,"ar":"<f><o>σταφυλή</o>، <g>-ῆς, ἡ </g></f> <s><b>عنقود عنب</b>: <r v=\"Matt.7.16\"></r>، <r v=\"Luke.6.44\"></r>، <r v=\"Rev.14.18\"></r>. «<g>σ.</g> هو في الأصل عنقود العنب الناضج في مقابل <g>ὄμφαξ</g>، قارن <r v=\"Gen.40.10\"></r>، <r v=\"Job.15.33\"></r>؛ وإذا قورن بـ<g>βότρυς</g> فهو يصف حبّات العنب أكثر مما يصف العنقود الذي تنمو عليه».†</s>","en":"<f><o>σταφυλή</o>, <g>-ῆς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6025\">עֵנָב</h> ;] </e> </et> <s>a<b> bunch of grapes</b>: <r v=\"Matt.7.16\"></r>, <r v=\"Luke.6.44\"></r>, <r v=\"Rev.14.18\"></r>. \"<g>σ.</g> is properly the ripe grape-cluster as opp. to <g>ὄμφαξ</g>, cf. <r v=\"Gen.40.10\"></r>, <r v=\"Job.15.33\"></r>; as contrasted with <g>βότρυς</g>, it describes the grapes rather than the cluster on which they grow\" (Swete, <i>Apoc.</i>, 187 f.).†</s>"},"G4763":{"l":"στρηνιάω","o":2,"ar":"<f>** <o>στρηνιάω</o>، <g>-ῶ</g></f> <s><b>عاش في البطر والتنعّم، تبطّر</b>: <r v=\"Rev.18.7\"></r>، <r v=\"Rev.18.9\"></r> (قارن <g>κατα-στρηνιάω</g>).†</s>","en":"<f>** <o>στρηνιάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στρῆνος</g></x>, q.v.), </e> <e t=\"septuagint\">[in Sm.: <r v=\"Isa.61.6\"></r> (<h n=\"H398\">אכל</h>) * ;]</e> </et> <s>a word which first appears in the middle comedy (Rutherford, <i>NPhr.</i>, 475 f.), <b>to run riot, wax wanton</b>: <r v=\"Rev.18.7\"></r>, <r v=\"Rev.18.9\"></r> (cf. <g>κατα-στρηνιάω</g>).†</s> <sy><i>SYN.</i>: <x><g>σπαταλάω</g></x> (q.v.), <x><g>τρυφάω</g></x> </sy>"},"G4740":{"l":"στηριγμός","o":1,"ar":"<f>** <o>στηριγμός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\"><b>تثبيت، إسناد</b>. </s> <s n=\"2.\"><b>ثبات، رسوخ</b>: <r v=\"2Pet.3.17\"></r>.†</s>","en":"<f>** <o>στηριγμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στηρίζω</g></x>), </e> <e t=\"septuagint\">[in Sm.: <r v=\"Isa.3.1\"></r> * ;] </e> </et> <s n=\"1.\"><b>a setting firmly, supporting</b>. </s> <s n=\"2.\"><b>fixedness, firmness, steadfastness</b>: <r v=\"2Pet.3.17\"></r>.†</s>"},"G4778":{"l":"συνκακουχέομαι","o":1,"ar":"<f>*† <o>συν-κακουχέομαι</o>، <g>-οῦμαι</g>، مبني للمجهول </f> <s><b>احتمل المشقّات مع</b>: مع القابل للشخص، <r v=\"Heb.11.25\"></r>. لا يرد في موضع آخر.†</s>","en":"<f>*† <o>συν-κακουχέομαι</o> (Rec. <g>συγκ-</g>), <g>-οῦμαι</g>, pass. </f> <s><b>to endure adversity with</b>: c. dat. pers., <r v=\"Heb.11.25\"></r>. Not elsewhere.†</s>"},"G4701":{"l":"σπορά","o":1,"ar":"<f><o>σπορά</o>، <g>-ᾶς, ἡ</g></f> <s n=\"1.\"><b>بَذْر (فعل الزرع)</b>. </s> <s n=\"2.\"><b>وقت الزرع</b>. </s> <s n=\"3.\"><b>زرع</b> مبذور: <r v=\"1Pet.1.23\"></r> </s> <s>(قارن <g>σπέρμα</g>).†</s>","en":"<f><o>σπορά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σπείρω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.19.29\"></r> (<h n=\"H2232\">זרע</h>), <r v=\"1Macc.10.30\"></r> * ;]</e> </et> <s n=\"1.\"><b>a sowing</b>. </s> <s n=\"2.\"><b>seedtime</b>. </s> <s n=\"3.\"><b>seed</b> sown (of human offspring, Soph., <i>Tr.</i>, 316, 420): <r v=\"1Pet.1.23\"></r> </s> <s>(cf. <g>σπέρμα</g>, and v. Milligan, <i>NTD</i>, 105 f.).†</s>"},"G4713":{"l":"στάμνος","o":1,"ar":"<f><o>στάμνος</o>، <g>-ου (ὁ</g> و)، <g>ἡ </g></f> <s>أصلاً، <b>جرّة فخارية</b> لتصفية الخمر؛ ومن ثمّ عمومًا، <b>جرّة، إناء</b>: <r v=\"Heb.9.4\"></r>.†</s>","en":"<f><o>στάμνος</o>, <g>-ου (ὁ</g> and), <g>ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.16.33\"></r> (<h n=\"H6803\">צִנְצֶנֶת</h>), <r v=\"1Kgs.12.24\"></r> <r v=\"1Kgs.14.3\"></r> (<h n=\"H1228\">בַּקְבֻּק</h>), Da LXX Bel <i>32</i> * ;] </e> </et> <s>prop., <b>an earthen jar</b> for racking off wine, hence, generally, <b>a jar</b>: <r v=\"Heb.9.4\"></r>.†</s>"},"G4749":{"l":"στολή","o":9,"ar":"<f><o>στολή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>عُدّة، عتاد</b>. </s> <s n=\"2.\">عُدّة من الثياب: <b>لباس</b>، وخاصةً <b>ثوب طويل فضفاض، حُلّة احتفالية</b>: (قارن <r v=\"Jon.3.6\"></r>، <r v=\"Ezra.8.15\"></r>، <r v=\"1Macc.6.15\"></r>): <r v=\"Mark.12.38\"></r> <r v=\"Mark.16.5\"></r>، <r v=\"Luke.15.22\"></r> <r v=\"Luke.20.46\"></r>، <r v=\"Rev.6.11\"></r> <r v=\"Rev.7.9\"></r>، <r v=\"Rev.7.13-Rev.7.14\"></r> <r v=\"Rev.22.14\"></r>.†</s>","en":"<f><o>στολή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στέλλω</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H899\">בֶּגֶד</h>, also for <h n=\"H3830\">לְבֻשׁ</h>, etc. ;]</e> </et> <s n=\"1.\"><b>an equipment, an armament</b> (Æsch.). </s> <s n=\"2.\">Equipment in clothes, <b>apparel</b>, esp. <b>flowing raiment, a festal robe</b>: (cf. <r v=\"Jon.3.6\"></r>, <r v=\"Ezra.8.15\"></r>, <r v=\"1Macc.6.15\"></r>): <r v=\"Mark.12.38\"></r> <r v=\"Mark.16.5\"></r>, <r v=\"Luke.15.22\"></r> <r v=\"Luke.20.46\"></r>, <r v=\"Rev.6.11\"></r> <r v=\"Rev.7.9\"></r>, <r v=\"Rev.7.13-Rev.7.14\"></r> <r v=\"Rev.22.14\"></r>.†</s>"},"G4738":{"l":"στῆθος","o":5,"ar":"<f><o>στῆθος</o>، <g>-ους, τό </g></f> <s><b>الصدر</b>: <r v=\"John.13.25\"></r> <r v=\"John.21.10\"></r>، <r v=\"Rev.15.6\"></r>؛ وعلامةً على التوبة، <g>τύπτειν</g> (<g>εἰς</g>) <g>τὸ σ.</g>، <r v=\"Luke.18.13\"></r> <r v=\"Luke.23.48\"></r>،†</s>","en":"<f><o>στῆθος</o>, <g>-ους, τό </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.28.23\"></r>, <r v=\"Exod.28.26\"></r> (<h n=\"H3820\">לֵב</h>), etc. ;] </e> </et> <s><b>the breast</b>: <r v=\"John.13.25\"></r> <r v=\"John.21.10\"></r>, <r v=\"Rev.15.6\"></r>; as a sign of penitence, <g>τύπτειν</g> (<g>εἰς</g>) <g>τὸ σ.</g>, <r v=\"Luke.18.13\"></r> <r v=\"Luke.23.48\"></r>,†</s>"},"G4761":{"l":"στρεβλόω","o":1,"ar":"<f><o>στρεβλόω</o>، <g>-ῶ</g></f> <s><b>لوى، عذّب (على آلة التعذيب)</b>. مجازيًا (قارن <r v=\"2Sam.22.27\"></r>): <b>لوى</b> أو <b>حرّف</b> الكلام: <r v=\"2Pet.3.16\"></r>.†</s>","en":"<f><o>στρεβλόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στρέφω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.22.27\"></r> (<h n=\"H6617\">פּתל</h> hithp.), <r v=\"3Macc.4.14\"></r>, <r v=\"4Macc.9.17\"></r> <r v=\"4Macc.12.4\"></r>, <r v=\"4Macc.12.11\"></r> <r v=\"4Macc.15.14\"></r> * ;]</e> </et> <s><b>to twist, torture</b>. Metaph. (cf. <r v=\"2Sam.22.27\"></r>), <b>to twist</b> or <b>pervert</b> language: <r v=\"2Pet.3.16\"></r>.†</s>"},"G4762":{"l":"στρέφω","o":21,"ar":"<f><o>στρέφω </o></f> <s><b>حوّل، أدار</b>: مع منصوب الشيء وقابل الشخص، <r v=\"Matt.5.39\"></r>؛ = <g>ἀποσ-</g>، <b>أرجع، ردّ</b>، <r v=\"Matt.27.3\"></r> (قارن <r v=\"Isa.38.8\"></r>)؛ بمعنى انعكاسي، <b>التفت</b>، <r v=\"Acts.7.42\"></r>؛ مع المنصوب يليه <g>εἰς</g>، = <g>μετασ-</g>، <b>حوّل، غيّر</b>، <r v=\"Rev.11.6\"></r>. المبني للمجهول، بمعنى انعكاسي، <b>التفت</b>: يليه <g>εἰς</g>، <r v=\"John.20.14\"></r>، <r v=\"Acts.7.39\"></r>، <r v=\"Acts.13.46\"></r>؛ اسم الفاعل <g>στραφείς</g>، مع الإخباري، <r v=\"Matt.7.6\"></r>، <r v=\"Matt.9.22\"></r>، <r v=\"Matt.16.23\"></r>، <r v=\"Luke.7.9\"></r>، <r v=\"Luke.9.55\"></r>، <r v=\"Luke.14.25\"></r>، <r v=\"Luke.22.61\"></r>، <r v=\"John.1.38\"></r>، <r v=\"John.20.16\"></r>؛ وكذلك يليه <g>πρός</g>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.10.22\"></r>، <r v=\"Luke.7.23\"></r>، <r v=\"Luke.23.28\"></r>؛ مجازيًا، <b>تغيّر، رجع</b>: مطلقًا، <r v=\"Matt.18.3\"></r>، <r v=\"John.12.40\"></r> (قارن <g>ἀνα-</g>، <g>ἀπο-</g>، <g>δια-</g>، <g>ἐκ</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>μετα-</g>، <g>συ(ν)-, ὑπο-στρέφω</g>).†</s>","en":"<f><o>στρέφω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2015\">הפך</h>, also for <h n=\"H5437\">סבב</h>, etc. ;]</e> </et> <s><b>to turn</b>: c. acc. rei dat. pers., <r v=\"Matt.5.39\"></r>; = <g>ἀποσ-</g>, <b>to bring back</b>, <r v=\"Matt.27.3\"></r> (cf. <r v=\"Isa.38.8\"></r>); reflexively (WM, § 38, 1), <b>to turn oneself</b>, <r v=\"Acts.7.42\"></r>; c. acc. seq. <g>εἰς</g>, = <g>μετασ-</g>, <b>to change</b>, <r v=\"Rev.11.6\"></r>. Pass., reflexive, <b>to turn oneself</b>: seq. <g>εἰς</g>, <r v=\"John.20.14\"></r>, <r v=\"Acts.7.39\"></r> <r v=\"Acts.13.46\"></r>; ptcp., <g>στραφείς</g>, c. indic., <r v=\"Matt.7.6\"></r> <r v=\"Matt.9.22\"></r> <r v=\"Matt.16.23\"></r>, <r v=\"Luke.7.9\"></r> <r v=\"Luke.9.55\"></r> <r v=\"Luke.14.25\"></r> <r v=\"Luke.22.61\"></r>, <r v=\"John.1.38\"></r> <r v=\"John.20.16\"></r>; id. seq. <g>πρός</g>, <r v=\"Luke.7.44\"></r> <r v=\"Luke.10.22\"></r> (WH, R, om.), <r v=\"Luke.7.23\"></r> <r v=\"Luke.23.28\"></r>; metaph., <b>to change</b>: absol., <r v=\"Matt.18.3\"></r>, <r v=\"John.12.40\"></r> (cf. <g>ἀνα-</g>, <g>ἀπο-</g>, <g>δια-</g>, <g>ἐκ</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>μετα-</g>, <g>συ(ν)-, ὑπο-στρέφω</g>).†</s>"},"G4753":{"l":"στράτευμα","o":8,"ar":"<f>** <o>στράτευμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: = <g>στρατεία</g>. </s> <s n=\"2.\"><b>جيش، جند</b>: في الجمع، <r v=\"Matt.22.7\"></r>، <r v=\"Rev.9.16\"></r>، <r v=\"Rev.19.14\"></r>، <r v=\"Rev.19.19\"></r>؛ = <b>عسكر، فرقة من الجنود</b>، <r v=\"Acts.23.10\"></r>، <r v=\"Acts.23.27\"></r>؛ في الجمع، <r v=\"Luke.23.11\"></r>.†</s>","en":"<f>** <o>στράτευμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στρατεύω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.9.34\"></r>, <r v=\"2Macc.5.24\"></r> <r v=\"2Macc.8.21\"></r> <r v=\"2Macc.12.38\"></r> <r v=\"2Macc.13.13\"></r>; pl., <r v=\"Jdt.11.8\"></r>, <r v=\"4Macc.5.1\"></r> * ;]</e> </et> <s n=\"1.\">= <g>στρατεία</g> (Hdt., al.). </s> <s n=\"2.\"><b>an army, a host</b>: pl., <r v=\"Matt.22.7\"></r>, <r v=\"Rev.9.16\"></r> <r v=\"Rev.19.14\"></r>, <r v=\"Rev.19.19\"></r>; = <b>soldiers, company of soldiers</b>, <r v=\"Acts.23.10\"></r>, <r v=\"Acts.23.27\"></r>; pl., <r v=\"Luke.23.11\"></r>.†</s>"},"G4700":{"l":"σποδός","o":3,"ar":"<f><o>σποδός</o>، <g>-οῦ, ὁ </g></f> <s><b>رماد</b>: <r v=\"Heb.9.13\"></r>؛ <g>ἐν σάκκῳ καὶ σ.</g> (<r v=\"Isa.58.5\"></r>، <r v=\"John.3.6\"></r>، <r v=\"Dan.9.3\"></r>، وفي مواضع أخرى)، <r v=\"Matt.11.21\"></r>، <r v=\"Luke.10.13\"></r>.†</s>","en":"<f><o>σποδός</o>, <g>-οῦ, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H665\">אֵפֶר</h> ;] </e> </et> <s><b>ashes</b>: <r v=\"Heb.9.13\"></r>; <g>ἐν σάκκῳ καὶ σ.</g> (<r v=\"Isa.58.5\"></r>, <r v=\"John.3.6\"></r>, <r v=\"Dan.9.3\"></r>, al.), <r v=\"Matt.11.21\"></r>, <r v=\"Luke.10.13\"></r>.†</s>"},"G4715":{"l":"στατήρ","o":1,"ar":"<f><o>στατήρ</o>، <g>-ῆρος, ὁ </g></f> <s><b>إستار</b>؛ </s> <s n=\"(a)\">وزن؛ </s> <s n=\"(b)\">عملة (استعمله الكتّاب المتأخرون للـ<g>τετράδραχμον</g> اليوناني): <r v=\"Matt.17.27\"></r>، <r v=\"Matt.26.16\"></r>.†</s>","en":"<f><o>στατήρ</o>, <g>-ῆρος, ὁ </g></f> <et> <e t=\"septuagint\">[in Aq., Sm., for <h n=\"H4948\">שֶׁקֶל</h> ;]</e> </et> <s><b>a stater</b>; </s> <s n=\"(a)\">a weight; </s> <s n=\"(b)\">a coin (used by late writers of the Greek <g>τετράδραχμον</g>): <r v=\"Matt.17.27\"></r> <r v=\"Matt.26.16\"></r>, WH, mg.†</s>"},"G4792":{"l":"συνκομίζω","o":1,"ar":"<f><o>συν-κομίζω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>جمع، حشد</b>. </s> <s n=\"2.\"><b>حمل</b> جثمانًا لدفنه: <r v=\"Acts.8.2\"></r>.†</s>","en":"<f><o>συν-κομίζω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.5.26\"></r> (<h n=\"H5927\">עלה</h>) * ;]</e> </et> <s n=\"1.\"><b>to bring together, collect</b> (Hdt., Xen., al.). </s> <s n=\"2.\"><b>to take up</b> a body for burial (Soph., <i>Aj.</i>, 1048): <r v=\"Acts.8.2\"></r> (v. Field, <i>Notes</i>, 116).†</s>"},"G4736":{"l":"Στέφανος","o":7,"ar":"<f><o>Στέφανος</o>، <g>-ου, ὁ </g></f> <s><b>استفانوس</b>: <r v=\"Acts.6.5\"></r>، <r v=\"Acts.6.8-Acts.6.9\"></r>، <r v=\"Acts.7.59\"></r>، <r v=\"Acts.8.2\"></r>، <r v=\"Acts.11.19\"></r>، <r v=\"Acts.22.20\"></r>.†</s>","en":"<f><o>Στέφανος</o>, <g>-ου, ὁ </g></f> <s><b>Stephen</b>: <r v=\"Acts.6.5\"></r>, <r v=\"Acts.6.8-Acts.6.9\"></r> <r v=\"Acts.7.59\"></r> <r v=\"Acts.8.2\"></r> <r v=\"Acts.11.19\"></r> <r v=\"Acts.22.20\"></r>.†</s>"},"G4797":{"l":"συνχέω","o":5,"ar":"<f><o>συν-χέω</o></f> <s><b>صبَّ معًا، خلط، شوَّش</b>؛ مجازيًا، <b>حيَّر، أهاج، أثار الاضطراب</b>: <r v=\"Acts.21.27\"></r> (قارن <g>συν-χύννω</g>).†</s>","en":"<f><o>συν-χέω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγ-</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H1101\">בּלל</h>, <h n=\"H7264\">רגז</h>, etc. ;]</e> </et> <s><b>to pour together, commingle, confuse</b>; metaph., <b>confound, throw into confusion, stir up trouble</b>: <r v=\"Acts.21.27\"></r> (cf. <g>συν-χύννω</g>).†</s>"},"G4719":{"l":"στάχυς","o":5,"ar":"<f><o>στάχυς</o>، <g>-υος, ὁ </g></f> <s><b>سنبلة</b>: <r v=\"Matt.12.1\"></r>، <r v=\"Mark.2.23\"></r>، <r v=\"Mark.4.28\"></r>، <r v=\"Luke.6.1\"></r>.†</s>","en":"<f><o>στάχυς</o>, <g>-υος, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7641\">שִׁבֹּלֶת</h> ;] </e> </et> <s><b>an ear of corn</b>: <r v=\"Matt.12.1\"></r>, <r v=\"Mark.2.23\"></r> <r v=\"Mark.4.28\"></r>, <r v=\"Luke.6.1\"></r>.†</s>"},"G4728":{"l":"στενός","o":3,"ar":"<f><o>στενός</o>، <g>-ή, -όν </g></f> <s><b>ضيّق</b>: مجازيًا، <r v=\"Matt.7.13-Matt.7.14\"></r>، <r v=\"Luke.13.24\"></r>.†</s>","en":"<f><o>στενός</o>, <g>-ή, -όν </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6862\">צַר</h>, etc. ;]</e> </et> <s><b>narrow</b>: fig (v MM, xxiii), <r v=\"Matt.7.13-Matt.7.14\"></r>, <r v=\"Luke.13.24\"></r>.†</s>"},"G4770":{"l":"Στωικός","o":null,"ar":"<f><o>Στωικός</o>، <g>-ή, -όν</g>، </f> <s><b>رواقي</b>: <r v=\"Acts.17.18\"></r>.†</s>","en":"<f><o>Στωικός</o> (Rec. <g>-ϊκός</g>, T, <g>Στοϊκός</g>), <g>-ή, -όν</g>, </f> <s><b>Stoic</b>: <r v=\"Acts.17.18\"></r>.†</s>"},"G4780":{"l":"συνκαλύπτω","o":1,"ar":"<f><o>συν-καλύπτω</o></f> <s><b>غطّى أو ستر تمامًا</b>: مع المنصوب، المبني للمجهول، <r v=\"Luke.12.2\"></r>.†</s>","en":"<f><o>συν-καλύπτω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3680\">כּסה</h> pi. ;] </e> </et> <s><b>to veil or cover completely</b>: c. acc., pass., <r v=\"Luke.12.2\"></r>.†</s>"},"G4721":{"l":"στέγη","o":3,"ar":"<f><o>στέγη</o>، <g>-ης, ἡ</g></f> <s><b>سقف</b>: <r v=\"Mark.2.4\"></r>؛ عن دخول البيت، <g>εἰσέρχεσθαι ὑπὸ τὴν σ.</g>، <r v=\"Matt.8.8\"></r>، <r v=\"Luke.7.6\"></r>.†</s>","en":"<f><o>στέγη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στέγω</g></x>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.8.13\"></r> (<h n=\"H4374\">מִכְסֶה</h>), etc. ;] </e> </et> <s><b>a roof</b>: <r v=\"Mark.2.4\"></r>; of entering a house, <g>εἰσέρχεσθαι ὑπὸ τὴν σ.</g>, <r v=\"Matt.8.8\"></r>, <r v=\"Luke.7.6\"></r> (cf. MM, xxiii).†</s>"},"G4744":{"l":"στίλβω","o":1,"ar":"<f><o>στίλβω </o></f> <s><b>يلمع، يتلألأ</b>: <r v=\"Mark.9.3\"></r>.†</s>","en":"<f><o>στίλβω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Nah.3.3\"></r> (<h n=\"H3851\">לַהַב</h>), etc. ;]</e> </et> <s><b>to shine, glisten</b>: <r v=\"Mark.9.3\"></r>.†</s>"},"G4766":{"l":"στρωννύω","o":6,"ar":"<f><o>στρωννύω</o> أو <g>στρώννυμι</g></f> <s><b>فرش، بسط</b>: <g>ἱμάτια ἐν τ. ὁδῷ</g> (<g>εἰς τ. ὁδόν</g>)، <r v=\"Matt.21.8\"></r>، <r v=\"Mark.11.8\"></r>؛ عن ترتيب الفراش، <g>στρῶσον</g> (أي <g>τ. κλίνην</g>) <g>σεαυτῷ</g>، <r v=\"Acts.9.34\"></r>؛ وعن تجهيز غرفة، <g>ἐστρωμένον</g>: <b>مفروشة</b> بالبُسط أو بالأرائك المفروشة (قارن <r v=\"Ezek.23.41\"></r>)، <r v=\"Mark.14.15\"></r>، <r v=\"Luke.22.12\"></r>.†</s>","en":"<f><o>στρωννύω</o> or <g>στρώννυμι</g></f> <et> <e t=\"derivation\">(v. Bl., § 23, 1; Veitch, s.v.), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3331\">יצע</h> hoph., etc. ;]</e> </et> <s><b>to spread</b>: <g>ἱμάτια ἐν τ. ὁδῷ</g> (<g>εἰς τ. ὁδόν</g>), <r v=\"Matt.21.8\"></r>, <r v=\"Mark.11.8\"></r>; of making a bed, <g>στρῶσον</g> (sc. <g>τ. κλίνην</g>) <g>σεαυτῷ</g>, <r v=\"Acts.9.34\"></r>; of furnishing a room, <g>ἐστρωμένον</g>, <b>spread</b> with carpets or carpeted couches (cf. <r v=\"Ezek.23.41\"></r>), <r v=\"Mark.14.15\"></r>, <r v=\"Luke.22.12\"></r>.†</s>"},"G4782":{"l":"συνκαταβαίνω","o":1,"ar":"<f><o>συν-κατα-βαίνω</o></f> <s><b>نزل مع</b>: <r v=\"Acts.25.5\"></r>. وعند الكتّاب المتأخرين أيضًا مجازيًا (<r v=\"Wis.10.13\"></r>): <b>تنازل</b>.†</s>","en":"<f><o>συν-κατα-βαίνω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.49.17\"></r> (<h n=\"H3381\">ירד</h>), <r v=\"Wis.10.13\"></r>, Da LXX TH 3:49 * ;] </e> </et> <s><b>to go down with</b>: <r v=\"Acts.25.5\"></r>. In late writers also metaph. (<r v=\"Wis.10.13\"></r>), <b>to condescend</b>, on wh. v. Rutherford, <i>NPhr.</i>, 485 f.†</s>"},"G4725":{"l":"στέμμα","o":1,"ar":"<f>* <o>στέμμα</o>، <g>-τος, τό</g></f> <s><b>إكليل، طوق من زهر</b>: كما يُستعمل في الذبائح، <r v=\"Acts.14.13\"></r>.†</s>","en":"<f>* <o>στέμμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>στέφω</g>, <b>to put around, enwreath</b>) </e> </et> <s><b>a wreath, garland</b>: as used in sacrifices, <r v=\"Acts.14.13\"></r>.†</s>"},"G4787":{"l":"συνκινέω","o":1,"ar":"<f>* <o>συν-κινέω</o>، <g>-ῶ</g>، </f> <s><b>حرّك معًا</b>. مجازيًا، <b>أثار، هيّج</b>: <g>τ. λαόν</g>، <r v=\"Acts.6.12\"></r>.†</s>","en":"<f>* <o>συν-κινέω</o> (Rec. <g>συγκ-</g>), <g>-ῶ</g>, </f> <s><b>to move together</b>. Metaph., <b>to excite, stir up</b>: <g>τ. λαόν</g>, <r v=\"Acts.6.12\"></r> (Arist., Polyb., al.).†</s>"},"G4746":{"l":"στοιβάς","o":1,"ar":"<f><o>στοιβάς</o>، انظر تحت مدخل <g>στιβάς</g>.</f>","en":"<f><o>στοιβάς</o>, v.s. <g>στιβάς</g>.</f>"},"G4768":{"l":"στυγνάζω","o":2,"ar":"<f>† <o>στυγνάζω</o></f> <s><b>كان ذا منظر كئيب عابس</b>: عن وجه الإنسان (في الترجمة المنقحة: <b>اغتمّ وجهه</b>)، <r v=\"Mark.10.22\"></r>؛ عن السماء، <r v=\"Matt.16.3\"></r>.†</s>","en":"<f>† <o>στυγνάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>στυγνός</g>, <b>sombre, gloomy, sullen</b>, <r v=\"Isa.5.17\"></r>, <r v=\"Wis.17.5\"></r>, <r v=\"Dan.2.12\"></r>*), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.27.35\"></r> <r v=\"Ezek.28.19\"></r> <r v=\"Ezek.32.10\"></r> (<h n=\"H8074\">שָׁמֵם</h>)* ;] </e> </et> <s><b>to have a sombre, gloomy appearance</b>: of the human countenance (RV,<b> his countenance fell</b>), <r v=\"Mark.10.22\"></r>; of the sky (so <g>στυγνότης</g>, Polyb., iv, 21, 1), <r v=\"Matt.16.3\"></r> (|[WH]|, R, mg., om.).†</s>"},"G4784":{"l":"συνκατατίθημι","o":1,"ar":"<f><o>συν-κατα-τίθημι</o></f> <s><b>أودع معًا</b>. الصيغة الوسطى، <b>أودع صوته مع</b>، ومن ثم <b>وافق على، رضي بـ</b>: مع القابل، <r v=\"Luke.23.51\"></r>.†</s>","en":"<f><o>συν-κατα-τίθημι</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.23.1\"></r> (<h n=\"H3027\">יָד</h> <h n=\"H7896\">שִׁית</h>), <r v=\"Exod.23.32\"></r> (<h n=\"H3772\">כּרת</h>), Da TH Su 1:20 * ;] </e> </et> <s><b>to deposit together</b>. Mid., <b>to deposit one's vote with</b>, hence, <b>to agree with, assent to</b>: c. dat., <r v=\"Luke.23.51\"></r>.†</s>"},"G4798":{"l":"συνχράομαι","o":1,"ar":"<f>**† <o>συν-χράομαι</o></f> <s><b>استعمل مع (اشترك في الاستعمال)</b>. مجازيًا، مع القابل للشخص، <b>عامل، خالط</b>: <r v=\"John.4.9\"></r>.†</s>","en":"<f>**† <o>συν-χράομαι</o></f> <et> <e t=\"derivation\">(Rec. <g>συγ-</g>), <g>-ῶμαι</g>, </e> <e t=\"septuagint\">[in Al.: <r v=\"1Sam.30.19\"></r> * ;]</e> </et> <s><b>to use together with</b>. Metaph., c. dat. pers., <b>to associate with</b>: <r v=\"John.4.9\"></r> (Polyb., al.).†</s>"},"G4799":{"l":"σύγχυσις","o":1,"ar":"<f><o>σύγχυσις</o>، <g>-εως, ἡ</g></f> <s><b>اضطراب، تشويش</b>: عن شغب شعبي، <r v=\"Acts.19.29\"></r>.†</s>","en":"<f><o>σύγχυσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>συγχέω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.11.9\"></r> (<h n=\"H894\">בָּבֶל</h>), <r v=\"1Sam.5.6\"></r>, <r v=\"1Sam.5.12\"></r> <r v=\"1Sam.14.20\"></r> (<h n=\"H4103\">מְהוּמָה</h>) * ;] </e> </et> <s><b>confusion</b>: of a popular uproar, <r v=\"Acts.19.29\"></r>.†</s>"},"G4756":{"l":"στρατιά","o":2,"ar":"<f><o>στρατιά</o>، <g>-ᾶς, ἡ </g></f> <s n=\"1.\">= <g>στρατός</g>، <b>جيش، جند</b>: عن الملائكة (<r v=\"1Kgs.22.19\"></r>، وفي مواضع أخرى)، <r v=\"Luke.2.13\"></r>؛ عن نجوم السماء (<r v=\"Jer.8.2\"></r>، <r v=\"2Chr.33.3\"></r>)، <r v=\"Acts.7.42\"></r>. </s> <s n=\"2.\">كما في الكلاسيكية أحيانًا (في الشعر)، = <g>στρατεία</g>: <r v=\"2Cor.10.4\"></r>.†</s>","en":"<f><o>στρατιά</o>, <g>-ᾶς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6635\">צָבָא</h> ;] </e> </et> <s n=\"1.\">= <g>στρατός</g>, <b>an army, a host</b>: of angels (<r v=\"1Kgs.22.19\"></r>, al.), <r v=\"Luke.2.13\"></r>; of the stars of heaven (<r v=\"Jer.8.2\"></r>, <r v=\"2Chr.33.3\"></r>), <r v=\"Acts.7.42\"></r>. </s> <s n=\"2.\">As sometimes in cl. (poët.), = <g>στρατεία</g>: <r v=\"2Cor.10.4\"></r>, T (WH, RV, <g>στρατεία</g>).†</s>"},"G4711":{"l":"σφυρίς","o":5,"ar":"<f>* <o>σφυρίς</o>، <g>-ίδος, ἡ</g>، </f> <s><b>سَلّ</b> لَيِّن مجدول كالحصير لحمل المؤونة: <r v=\"Matt.15.37\"></r> <r v=\"Matt.16.10\"></r>، <r v=\"Mark.8.8\"></r>، <r v=\"Mark.8.20\"></r> <r v=\"Acts.9.25\"></r> (انظر تحت مدخل <g>κόφινος</g>).†</s>","en":"<f>* <o>σφυρίς</o> (T, Rec. <g>σπυρίς</g>, v. WH, <i>App.</i>, 148; Bl., § 6, 7), <g>-ίδος, ἡ</g>, </f> <s>a flexible mat-<b>basket</b> for carrying provisions: <r v=\"Matt.15.37\"></r> <r v=\"Matt.16.10\"></r>, <r v=\"Mark.8.8\"></r>, <r v=\"Mark.8.20\"></r> <r v=\"Acts.9.25\"></r> (v.s. <g>κόφινος</g>).†</s>"},"G4745":{"l":"στοά","o":3,"ar":"<f><o>στοά</o>، <g>-ᾶς, ἡ </g></f> <s><b>رواق</b>: <r v=\"John.5.2\"></r>؛ ويُطلق على الرواق المسقوف ذي الأعمدة في الهيكل (في الترجمات الإنجليزية <b>رواق</b>)، <r v=\"John.10.23\"></r>، <r v=\"Acts.3.11\"></r> <r v=\"Acts.5.12\"></r> †</s>","en":"<f><o>στοά</o>, <g>-ᾶς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.40.18\"></r> (<h n=\"H7531\">רִצְפָּה</h>), etc. ;]</e> </et> <s><b>a portico</b>: <r v=\"John.5.2\"></r>; used of the covered colonnade in the Temple (EV,<b> porch</b>), <r v=\"John.10.23\"></r>, <r v=\"Acts.3.11\"></r> <r v=\"Acts.5.12\"></r> †</s>"},"G4775":{"l":"συνκάθημαι","o":2,"ar":"<f><o>συν-κάθημαι</o></f> <s><b>جلس معًا أو مع</b>: مع القابل، <r v=\"Acts.26.30\"></r>؛ يليه <g>μετά</g>، مع المضاف إليه، <r v=\"Mark.14.54\"></r>.†</s>","en":"<f><o>συν-κάθημαι</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.101.6\"></r> (<h n=\"H3427\">ישׁב</h>) * ;]</e> </et> <s><b>to sit together or with</b>: c. dat., <r v=\"Acts.26.30\"></r>; seq. <g>μετά</g>, c. gen., <r v=\"Mark.14.54\"></r>.†</s>"},"G4760":{"l":"στρατόπεδον","o":1,"ar":"<f><o>στρατό-πεδον</o>، <g>-ου, τό</g></f> <s n=\"(a)\"><b>معسكر</b>؛ </s> <s n=\"(b)\"><b>جيش، جنود</b>: <r v=\"Luke.21.20\"></r>.†</s>","en":"<f><o>στρατό-πεδον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(<g>στρατός</g> + <g>πέδον</g>, <b>a plain</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.34.1\"></r> (<h n=\"H2428\">חַיִל</h>), <r v=\"2Macc.8.12\"></r>, al. ;] </e> </et> <s n=\"(a)\"><b>a military camp</b>; </s> <s n=\"(b)\"><b>an army</b>: <r v=\"Luke.21.20\"></r>.†</s>"},"G4779":{"l":"συνκαλέω","o":8,"ar":"<f><o>συν-καλέω</o></f> <s><b>دعا معًا، جمع</b>: مع المنصوب، <r v=\"Mark.15.16\"></r>، <r v=\"Luke.15.6\"></r>، <r v=\"Luke.15.9\"></r>، <r v=\"Acts.5.21\"></r>. الصيغة الوسطى، <b>دعا إليه، جمع إليه</b>: <r v=\"Luke.9.1\"></r> (قارن <r v=\"Luke.15.6\"></r>، <r v=\"Luke.15.9\"></r>) <r v=\"Luke.23.13\"></r>، <r v=\"Acts.10.24\"></r> <r v=\"Acts.28.17\"></r>.†</s>","en":"<f><o>συν-καλέω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), <g>-ῶ</g>, </e> <e t=\"septuagint\">[in LXX for <h n=\"H7121\">קרא</h> ;] </e> </et> <s><b>to call together</b>: c. acc., <r v=\"Mark.15.16\"></r>, <r v=\"Luke.15.6\"></r>, <r v=\"Luke.15.9\"></r> (v.l. <g>-εῖται</g>, v. B1., § 55, 1), <r v=\"Acts.5.21\"></r>. Mid., <b>to call together to oneself </b>: <r v=\"Luke.9.1\"></r> (and v.l. in <r v=\"Luke.15.6\"></r>, <r v=\"Luke.15.9\"></r> v. supr.) <r v=\"Luke.23.13\"></r>, <r v=\"Acts.10.24\"></r> <r v=\"Acts.28.17\"></r>.†</s>"},"G4785":{"l":"συνκαταψηφίζω","o":1,"ar":"<f>*† <o>συν-κατα-ψηφίζω</o>، </f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>دان مع غيره</b>. </s> <s n=\"2.\"><b>مُنح بالتصويت مكانًا بين</b>: المبني للمجهول، <r v=\"Acts.1.26\"></r>. ولا يرد في موضع آخر.†</s>","en":"<f>*† <o>συν-κατα-ψηφίζω</o> (Rec. <g>συγκ-</g>), </f> <s n=\"1.\"><b>to condemn with or together</b> (Plut., <i>Themist.</i>, 21). </s> <s n=\"2.\"><b>to vote one a place among</b>: pass., <r v=\"Acts.1.26\"></r>. Not elsewhere .†</s>"},"G4743":{"l":"στιγμή","o":1,"ar":"<f><o>στιγμή</o>، <g>-ῆς, ἡ</g></f> <s><b>نخسة، نقطة</b>؛ مجازيًا، <g>σ. χρόνου</g>، <b>لحظة</b>: <r v=\"Luke.4.5\"></r>.†</s>","en":"<f><o>στιγμή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>στίζω</g>, <b>to prick</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.29.5\"></r> (<h n=\"H6621\">פֶּתַע</h>), <r v=\"2Macc.9.11\"></r> * ;] </e> </et> <s><b>a prick, a point</b>; metaph., <g>σ. χρόνου</g>, <b>a moment</b>: <r v=\"Luke.4.5\"></r>.†</s>"},"G4755":{"l":"στρατηγός","o":10,"ar":"<f><o>στρατηγός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: قائد عسكري، <b>قائد جيش</b>. </s> <s n=\"2.\">قائد مدني، <b>حاكم، والٍ</b>: <r v=\"Acts.16.20\"></r>، <r v=\"Acts.16.22\"></r>، <r v=\"Acts.16.35-Acts.16.36\"></r>، <r v=\"Acts.16.38\"></r>. </s> <s n=\"3.\">قائد الحرس اللاوي في الهيكل، <g>ὁ σ. τ. ἱεροῦ</g> (<b>قائد جند الهيكل</b>): <r v=\"Acts.4.1\"></r> <r v=\"Acts.5.24\"></r>، <r v=\"Acts.5.26\"></r>؛ في الجمع، <r v=\"Luke.22.4\"></r>، <r v=\"Luke.22.52\"></r>.†</s>","en":"<f><o>στρατηγός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>στρατός</g>, <x><g>ἄγω</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5461\">סָגָן</h> (always in pl.), <h n=\"H8269\">שַׂר</h> ;]</e> </et> <s n=\"1.\">a military commander, <b>a general</b> (Hdt., al.). </s> <s n=\"2.\">A civic commander, <b>a governor, magistrate</b> (Hdt., Xen., al.): <r v=\"Acts.16.20\"></r>, <r v=\"Acts.16.22\"></r>, <r v=\"Acts.16.35-Acts.16.36\"></r>, <r v=\"Acts.16.38\"></r>. </s> <s n=\"3.\">The commander of the Levitical guard of the Temple, <g>ὁ σ. τ. ἱεροῦ</g> (EV, <b>captain of the Temple</b>): <r v=\"Acts.4.1\"></r> <r v=\"Acts.5.24\"></r>, <r v=\"Acts.5.26\"></r>; pl., <r v=\"Luke.22.4\"></r>, <r v=\"Luke.22.52\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἄρχων</g></x> (cf. <i>EGT</i> on <r v=\"Acts.16.20\"></r>; Ramsay, <i>St. Paul</i>, 217). </sy>"},"G4765":{"l":"στρουθίον","o":4,"ar":"<f><o>στρουθίον</o>، <g>-ου, τό </g></f> <s>تصغير <g>στρουθός</g> </s> <s><b>عصفور</b>: <r v=\"Matt.10.29\"></r>، <r v=\"Matt.10.31\"></r>، <r v=\"Luke.12.6-Luke.12.7\"></r>.†</s>","en":"<f><o>στρουθίον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6833\">צִפּוֹר</h> ;] </e> </et> <s>dimin. of <g>στρουθός</g> </s> <s><b>a sparrow</b>: <r v=\"Matt.10.29\"></r>, <r v=\"Matt.10.31\"></r>, <r v=\"Luke.12.6-Luke.12.7\"></r>.†</s>"},"G4794":{"l":"συνκύπτω","o":1,"ar":"<f><o>συν-κύπτω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>انحنى إلى الأمام</b>. </s> <s n=\"2.\"><b>كان منحنيًا</b>: <r v=\"Luke.13.11\"></r>.†</s>","en":"<f><o>συν-κύπτω</o></f> <et> <e t=\"derivation\">(Rec. <g>συγκ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.9.27\"></r> (<h n=\"H5800\">עזב</h>), <r v=\"Sir.12.11\"></r> <r v=\"Sir.19.26\"></r> * ;] </e> </et> <s n=\"1.\"><b>to bend forwards</b> (Arist., al.). </s> <s n=\"2.\"><b>to be bowed down</b>: <r v=\"Luke.13.11\"></r>.†</s>"},"G4732":{"l":"στερεόω","o":3,"ar":"<f><o>στερεόω</o>، <g>-ῶ</g></f> <s n=\"(a)\"><b>جعله ثابتًا</b> أو <b>صلبًا</b>؛ </s> <s n=\"(b)\"><b>شدّد، قوّى</b>؛ مع منصوب الشخص، <r v=\"Acts.3.16\"></r>؛ <g>τ. βάσεις</g>، المبني للمجهول، <r v=\"Acts.3.7\"></r>. مجازيًا (قارن <r v=\"Jer.5.3\"></r>): <g>τ. πίστει</g>، المبني للمجهول، <r v=\"Acts.16.5\"></r>.†</s>","en":"<f><o>στερεόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στερεός</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.42.5\"></r> (<h n=\"H7554\">רקע</h>), <r v=\"Jer.5.3\"></r> (<h n=\"H2388\">חזק</h> pi.), etc. ;] </e> </et> <s n=\"(a)\"><b>to make firm</b> or <b>solid</b>; </s> <s n=\"(b)\"><b>to strengthen, make strong</b>; c. acc. pers., <r v=\"Acts.3.16\"></r>; <g>τ. βάσεις</g>, pass., <r v=\"Acts.3.7\"></r>. Metaph. (cf. <r v=\"Jer.5.3\"></r>): <g>τ. πίστει</g>, pass., <r v=\"Acts.16.5\"></r>.†</s>"},"G4772":{"l":"συγγένεια","o":3,"ar":"<f><o>συγγένεια</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>قرابة</b>. </s> <s n=\"2.\">كنايةً، <b>الأقرباء، العشيرة</b>: <r v=\"Luke.1.61\"></r>، <r v=\"Acts.7.3\"></r>، <r v=\"Acts.7.14\"></r> †</s>","en":"<f><o>συγγένεια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συγγενής</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4940\">מִשְׁפָּחָה</h> ;] </e> </et> <s n=\"1.\"><b>kinship</b>. </s> <s n=\"2.\">By meton., <b>kinsfolk, kindred</b>: <r v=\"Luke.1.61\"></r>, <r v=\"Acts.7.3\"></r>, <r v=\"Acts.7.14\"></r> †</s>"},"G4702":{"l":"σπόριμος","o":3,"ar":"<f><o>σπόριμος</o>، <g>-ον</g></f> <s><b>صالح للزرع، مزروع</b>؛ اسمًا، <g>τὰ σ.</g>، <b>الزروع، حقول القمح</b>: <r v=\"Matt.12.1\"></r>، <r v=\"Mark.2.23\"></r>، <r v=\"Luke.6.1\"></r>.†</s>","en":"<f><o>σπόριμος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σπείρω</g></x>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.1.29\"></r>, <r v=\"Lev.11.37\"></r> (<h n=\"H2232\">זרע</h>), <r v=\"Sir.40.22\"></r> <h>א</h><i>1</i> * ;]</e> </et> <s><b>fit for sowing, sown</b>; as subst., <g>τὰ σ.</g>, <b>corn-fields</b>: <r v=\"Matt.12.1\"></r>, <r v=\"Mark.2.23\"></r>, <r v=\"Luke.6.1\"></r>.†</s>"},"G4795":{"l":"συγκυρία","o":1,"ar":"<f>** <o>συγκυρία</o>، <g>-ας, ἡ</g></f> <s><b>مصادفة، اتفاق</b>: <g>κατὰ σ.</g>، <r v=\"Luke.10.31\"></r>.†</s>","en":"<f>** <o>συγκυρία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>συγκυρέω</g>, <b>to happen</b>), </e> <e t=\"septuagint\">[in Sm.: <r v=\"1Sam.6.9\"></r> (<h n=\"H4745\">מִקְרֶה</h>) * ;]</e> <e t=\"derivation\">(more freq. in late writers, <g>συγκύρησις, -ημα</g>), </e> </et> <s><b>chance, coincidence</b>: <g>κατὰ σ.</g> (v. MM, xxiii), <r v=\"Luke.10.31\"></r> (Hippocr., Eccl.).†</s>"}});A.got[47]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});